            { "prompt": "\u0631\u062A\u0628 \u0627\u0644\u0643\u0644\u0645\u0627\u062A \u0644\u062A\u0643\u0648\u064A\u0646 \u062C\u0645\u0644\u0629 \u0635\u062D\u064A\u062D\u0629: (\u0644\u062F\u064A \u0641\u0643\u0631\u0629 \u062C\u064A\u062F\u0629.)", "words": ["idea / have / good / a / I"], "correct": ["I", "have", "a", "good", "idea"] },
            { "prompt": "\u0623\u0643\u0645\u0644 \u0627\u0644\u0641\u0631\u0627\u063A: \u0644\u064A\u0633 \u0644\u062F\u064A \u0645\u0627\u0644 : I do not have ___", "placeholder": "money / time / passport", "answer": "money" }
