            { "text": "We need to book a table.", "options": ["book", "seat", "bill"], "answer": "book", "hint": "\u064A\u062D\u062C\u0632 \u0637\u0627\u0648\u0644\u0629 \u0645\u0633\u0628\u0642\u0627\u064B" },
            { "text": "Can we have the bill?", "options": ["bill", "receipt", "change"], "answer": "bill", "hint": "\u0641\u0627\u062A\u0648\u0631\u0629 \u0627\u0644\u062D\u0633\u0627\u0628" }
