          "writing": [
            { "prompt": "\u0631\u062A\u0628 \u0627\u0644\u0643\u0644\u0645\u0627\u062A \u0644\u062A\u0643\u0648\u064A\u0646 \u062C\u0645\u0644\u0629 \u0635\u062D\u064A\u062D\u0629: (\u0627\u062D\u062C\u0632 \u0637\u0627\u0648\u0644\u0629 \u0644\u0644\u064A\u0644\u0629.)", "words": ["table / tonight / Book / a"], "correct": ["Book", "a", "table", "tonight"] },
            { "prompt": "\u0623\u0643\u0645\u0644 \u0627\u0644\u0641\u0631\u0627\u063A: \u0647\u0644 \u0647\u0630\u0627 \u0627\u0644\u0645\u0642\u0639\u062F \u0634\u0627\u063A\u0631\u061F : Is this ___ free?", "placeholder": "seat / bill / menu", "answer": "seat" },
            { "prompt": "\u0631\u062A\u0628 \u0627\u0644\u0643\u0644\u0645\u0627\u062A \u0644\u062A\u0643\u0648\u064A\u0646 \u062C\u0645\u0644\u0629 \u0635\u062D\u064A\u062D\u0629: (\u0623\u062A\u0645\u0646\u0649 \u0644\u0643 \u0648\u062C\u0628\u0629 \u0644\u0630\u064A\u0630\u0629.)", "words": ["yummy / a / Have / meal"], "correct": ["Have", "a", "yummy", "meal"] }
          ]
