  var lesson52;
  var init_lesson52 = __esm({
    "js/data/A2/units/unit2/lesson5.js"() {
      lesson52 = {
        id: 5,
        unitId: 2,
        title: "Asking for Directions",
        description: "Learn to ask for and give directions, navigate street blocks, and use prepositions of motion.",
        explanation: {
          intro: "\u0645\u0631\u062D\u0628\u0627\u064B \u0628\u0643 \u0641\u064A \u0627\u0644\u0648\u062D\u062F\u0629 \u0627\u0644\u062B\u0627\u0646\u064A\u0629! \u0633\u0646\u062A\u0639\u0644\u0645 \u0627\u0644\u064A\u0648\u0645 \u0643\u064A\u0641\u064A\u0629 \u0627\u0644\u0633\u0624\u0627\u0644 \u0639\u0646 \u0627\u0644\u0627\u062A\u062C\u0627\u0647\u0627\u062A \u0648\u0648\u0635\u0641 \u0627\u0644\u0637\u0631\u0642 \u0644\u0644\u0623\u0634\u062E\u0627\u0635 \u0627\u0644\u0622\u062E\u0631\u064A\u0646 \u0628\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u062D\u0631\u0648\u0641 \u0627\u0644\u062C\u0631 \u0627\u0644\u062E\u0627\u0635\u0629 \u0628\u0627\u0644\u062D\u0631\u0643\u0629 \u0648\u0627\u0644\u0645\u0643\u0627\u0646 \u0628\u0637\u0631\u064A\u0642\u0629 \u0635\u062D\u064A\u062D\u0629.",
          sections: [
            {
              title: "1. Prepositions of Motion (\u062D\u0631\u0648\u0641 \u0627\u0644\u062C\u0631 \u0627\u0644\u062E\u0627\u0635\u0629 \u0628\u0627\u0644\u062D\u0631\u0643\u0629)",
              content: "\u0646\u0633\u062A\u062E\u062F\u0645 \u0647\u0630\u0647 \u0627\u0644\u062D\u0631\u0648\u0641 \u0644\u0648\u0635\u0641 \u0645\u0633\u0627\u0631 \u0627\u0644\u062D\u0631\u0643\u0629 \u0648\u0627\u0644\u0627\u062A\u062C\u0627\u0647:\n- **Go past**: \u0627\u0630\u0647\u0628 \u0645\u062A\u062E\u0637\u064A\u0627\u064B (\u0645\u0631 \u0628\u062C\u0627\u0646\u0628).\n- **Go across / Cross**: \u0627\u0639\u0628\u0631 (\u0645\u062B\u0644 \u0627\u0644\u062C\u0633\u0631 \u0623\u0648 \u0627\u0644\u0634\u0627\u0631\u0639).\n- **Turn left / right**: \u0627\u062A\u062C\u0647 \u064A\u0633\u0627\u0631\u0627\u064B / \u064A\u0645\u064A\u0646\u0627\u064B.\n- **Go straight ahead**: \u0627\u0630\u0647\u0628 \u0645\u0628\u0627\u0634\u0631\u0629 \u0644\u0644\u0623\u0645\u0627\u0645."
            },
            {
              title: "2. Prepositions of Place for Locations (\u062D\u0631\u0648\u0641 \u0627\u0644\u062C\u0631 \u0644\u0644\u0645\u0648\u0642\u0639)",
              content: "\u0644\u062A\u062D\u062F\u064A\u062F \u0645\u0648\u0642\u0639 \u0645\u0628\u0646\u0649 \u0628\u0627\u0644\u0646\u0633\u0628\u0629 \u0644\u0645\u0628\u0646\u0649 \u0622\u062E\u0631:\n- **Opposite**: \u0645\u0642\u0627\u0628\u0644 (\u0641\u064A \u0627\u0644\u062C\u0647\u0629 \u0627\u0644\u0623\u062E\u0631\u0649 \u0645\u0646 \u0627\u0644\u0634\u0627\u0631\u0639).\n- **Next to**: \u0628\u062C\u0627\u0646\u0628.\n- **Between... and**: \u0628\u064A\u0646 (\u0634\u064A\u0626\u064A\u0646).\n- **At the corner**: \u0639\u0644\u0649 \u0627\u0644\u0646\u0627\u0635\u064A\u0629 / \u0639\u0646\u062F \u0627\u0644\u0632\u0627\u0648\u064A\u0629."
            }
          ]
        },
        vocabulary: [
          { id: 2117, word: "directions", translation: "\u0627\u062A\u062C\u0627\u0647\u0627\u062A / \u0625\u0631\u0634\u0627\u062F\u0627\u062A \u0627\u0644\u0637\u0631\u064A\u0642", example: "Can you give me directions?", exampleTranslation: "\u0645\u0645\u0643\u0646 \u062A\u0648\u0635\u0641 \u0644\u064A \u0627\u0644\u0637\u0631\u064A\u0642\u061F" },
          { id: 2118, word: "maps", translation: "\u062E\u0631\u0627\u0626\u0637", example: "Google Maps is helpful.", exampleTranslation: "\u062E\u0631\u0627\u0626\u0637 \u062C\u0648\u062C\u0644 \u0645\u0641\u064A\u062F\u0629." },
          { id: 2119, word: "ask", translation: "\u064A\u0633\u0623\u0644", example: "Ask the policeman for help.", exampleTranslation: "\u0627\u0633\u0623\u0644 \u0627\u0644\u0634\u0631\u0637\u064A \u0644\u0644\u0645\u0633\u0627\u0639\u062F\u0629." },
          { id: 2120, word: "find", translation: "\u064A\u062C\u062F", example: "I cannot find my hotel.", exampleTranslation: "\u0645\u0634 \u0644\u0627\u0642\u064A \u0627\u0644\u0641\u0646\u062F\u0642 \u0628\u062A\u0627\u0639\u064A." },
          { id: 2121, word: "show", translation: "\u064A\u0648\u0636\u062D / \u064A\u0631\u064A", example: "Show me the way, please.", exampleTranslation: "\u0648\u0631\u064A\u0646\u064A \u0627\u0644\u0637\u0631\u064A\u0642 \u0644\u0648 \u0633\u0645\u062D\u062A." },
          { id: 2122, word: "turn left", translation: "\u0627\u0646\u0639\u0637\u0641 \u064A\u0633\u0627\u0631\u0627\u064B", example: "Turn left at the bank.", exampleTranslation: "\u0627\u062D\u0648\u062F \u0634\u0645\u0627\u0644 \u0639\u0646\u062F \u0627\u0644\u0628\u0646\u0643." },
          { id: 2123, word: "turn right", translation: "\u0627\u0646\u0639\u0637\u0641 \u064A\u0645\u064A\u0646\u0627\u064B", example: "Turn right after the school.", exampleTranslation: "\u0627\u062D\u0648\u062F \u064A\u0645\u064A\u0646 \u0628\u0639\u062F \u0627\u0644\u0645\u062F\u0631\u0633\u0629." },
          { id: 2124, word: "go straight", translation: "\u0627\u0630\u0647\u0628 \u0645\u0628\u0627\u0634\u0631\u0629 \u0644\u0644\u0623\u0645\u0627\u0645", example: "Go straight for two blocks.", exampleTranslation: "\u0627\u0645\u0634\u064A \u0639\u0644\u0637\u0648\u0644 \u0644\u0645\u0633\u0627\u0641\u0629 \u062A\u0642\u0627\u0637\u0639\u064A\u0646." },
          { id: 2125, word: "cross", translation: "\u064A\u0639\u0628\u0631", example: "Cross the street carefully.", exampleTranslation: "\u0639\u062F\u064A \u0627\u0644\u0634\u0627\u0631\u0639 \u0628\u062D\u0631\u0635." },
          { id: 2126, word: "bridge", translation: "\u062C\u0633\u0631 / \u0643\u0648\u0628\u0631\u064A", example: "Go across the Nile bridge.", exampleTranslation: "\u0639\u062F\u064A \u0643\u0648\u0628\u0631\u064A \u0627\u0644\u0646\u064A\u0644." },
          { id: 2127, word: "corner", translation: "\u0646\u0627\u0635\u064A\u0629 / \u0632\u0627\u0648\u064A\u0629", example: "The shop is on the corner.", exampleTranslation: "\u0627\u0644\u0645\u062D\u0644 \u0639\u0644\u0649 \u0627\u0644\u0646\u0627\u0635\u064A\u0629." },
          { id: 2128, word: "street", translation: "\u0634\u0627\u0631\u0639", example: "This street is noisy.", exampleTranslation: "\u0627\u0644\u0634\u0627\u0631\u0639 \u062F\u0647 \u062F\u0648\u0634\u0629." },
          { id: 2129, word: "block", translation: "\u0645\u0631\u0628\u0639 \u0633\u0643\u0646\u064A / \u062A\u0642\u0627\u0637\u0639", example: "Walk one more block.", exampleTranslation: "\u0627\u0645\u0634\u064A \u0643\u0645\u0627\u0646 \u0645\u0631\u0628\u0639 \u0633\u0643\u0646\u064A \u0648\u0627\u062D\u062F." },
          { id: 2130, word: "traffic light", translation: "\u0625\u0634\u0627\u0631\u0629 \u0627\u0644\u0645\u0631\u0648\u0631", example: "Stop at the red traffic light.", exampleTranslation: "\u0627\u0642\u0641 \u0639\u0646\u062F \u0625\u0634\u0627\u0631\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u062D\u0645\u0631\u0627\u0621." },
          { id: 2131, word: "roundabout", translation: "\u0635\u064A\u0646\u064A\u0629 / \u0645\u064A\u062F\u0627\u0646 \u062F\u0648\u0631\u0627\u0646\u064A", example: "Take the second exit at the roundabout.", exampleTranslation: "\u062E\u062F \u0627\u0644\u0645\u062E\u0631\u062C \u0627\u0644\u062A\u0627\u0646\u064A \u0639\u0646\u062F \u0627\u0644\u0645\u064A\u062F\u0627\u0646." },
          { id: 2132, word: "sign", translation: "\u0644\u0627\u0641\u062A\u0629 / \u0639\u0644\u0627\u0645\u0629", example: "Follow the road signs.", exampleTranslation: "\u0627\u062A\u0628\u0639 \u0644\u0627\u0641\u062A\u0627\u062A \u0627\u0644\u0637\u0631\u064A\u0642." },
          { id: 2133, word: "opposite", translation: "\u0645\u0642\u0627\u0628\u0644 / \u0641\u064A \u0627\u0644\u062C\u0647\u0629 \u0627\u0644\u0623\u062E\u0631\u0649", example: "The museum is opposite the park.", exampleTranslation: "\u0627\u0644\u0645\u062A\u062D\u0641 \u0641\u064A \u0645\u0648\u0627\u062C\u0647\u0629 \u0627\u0644\u062D\u062F\u064A\u0642\u0629." },
          { id: 2134, word: "next to", translation: "\u0628\u062C\u0627\u0646\u0628", example: "The bank is next to the post office.", exampleTranslation: "\u0627\u0644\u0628\u0646\u0643 \u062C\u0646\u0628 \u0645\u0643\u062A\u0628 \u0627\u0644\u0628\u0631\u064A\u062F." },
          { id: 2135, word: "between", translation: "\u0628\u064A\u0646", example: "The cafe is between the school and the library.", exampleTranslation: "\u0627\u0644\u0642\u0647\u0648\u0629 \u0628\u064A\u0646 \u0627\u0644\u0645\u062F\u0631\u0633\u0629 \u0648\u0627\u0644\u0645\u0643\u062A\u0628\u0629." },
          { id: 2136, word: "behind", translation: "\u062E\u0644\u0641", example: "The parking lot is behind the building.", exampleTranslation: "\u0645\u0648\u0642\u0641 \u0627\u0644\u0633\u064A\u0627\u0631\u0627\u062A \u062E\u0644\u0641 \u0627\u0644\u0645\u0628\u0646\u0649." },
          { id: 2137, word: "near", translation: "\u0642\u0631\u064A\u0628 \u0645\u0646", example: "I live near the station.", exampleTranslation: "\u0623\u0646\u0627 \u0639\u0627\u064A\u0634 \u0642\u0631\u064A\u0628 \u0645\u0646 \u0627\u0644\u0645\u062D\u0637\u0629." },
          { id: 2138, word: "far", translation: "\u0628\u0639\u064A\u062F", example: "Is the airport far from here?", exampleTranslation: "\u0647\u0648 \u0627\u0644\u0645\u0637\u0627\u0631 \u0628\u0639\u064A\u062F \u0645\u0646 \u0647\u0646\u0627\u061F" },
          { id: 2139, word: "lost", translation: "\u062A\u0627\u0626\u0647 / \u0636\u0627\u0626\u0639", example: "Excuse me, I am lost.", exampleTranslation: "\u0644\u0648 \u0633\u0645\u062D\u062A\u060C \u0623\u0646\u0627 \u062A\u0627\u064A\u0647." },
          { id: 2140, word: "guide", translation: "\u0645\u0631\u0634\u062F / \u064A\u0631\u0634\u062F", example: "We hired a local guide.", exampleTranslation: "\u0623\u062C\u0631\u0646\u0627 \u0645\u0631\u0634\u062F \u0645\u062D\u0644\u064A." },
          { id: 2141, word: "tourist", translation: "\u0633\u0627\u0626\u062D", example: "Many tourists visit Luxor.", exampleTranslation: "\u0633\u064A\u0627\u062D \u0643\u062A\u064A\u0631 \u0628\u064A\u0632\u0648\u0631\u0648\u0627 \u0627\u0644\u0623\u0642\u0635\u0631." },
          { id: 2142, word: "location", translation: "\u0645\u0648\u0642\u0639 / \u0645\u0643\u0627\u0646", example: "Send me your location.", exampleTranslation: "\u0627\u0628\u0639\u062A \u0644\u064A \u0645\u0648\u0642\u0639\u0643." },
          { id: 2143, word: "building", translation: "\u0645\u0628\u0646\u0649", example: "That building is historic.", exampleTranslation: "\u0627\u0644\u0645\u0628\u0646\u0649 \u062F\u0647 \u062A\u0627\u0631\u064A\u062E\u064A." },
          { id: 2144, word: "station", translation: "\u0645\u062D\u0637\u0629", example: "Where is the train station?", exampleTranslation: "\u0641\u064A\u0646 \u0645\u062D\u0637\u0629 \u0627\u0644\u0642\u0637\u0631\u061F" },
          { id: 2145, word: "supermarket", translation: "\u0633\u0648\u0628\u0631 \u0645\u0627\u0631\u0643\u062A", example: "Buy milk from the supermarket.", exampleTranslation: "\u0627\u0634\u062A\u0631\u064A \u0644\u0628\u0646 \u0645\u0646 \u0627\u0644\u0633\u0648\u0628\u0631 \u0645\u0627\u0631\u0643\u062A." },
          { id: 2146, word: "library", translation: "\u0645\u0643\u062A\u0628\u0629 \u0627\u0644\u0642\u0631\u0627\u0621\u0629", example: "I study at the library.", exampleTranslation: "\u0628\u0630\u0627\u0643\u0631 \u0641\u064A \u0627\u0644\u0645\u0643\u062A\u0628\u0629." }
        ],
        dialogue: {
          title: "Finding the Museum",
          lines: [
            { speaker: "Tourist", text: "Excuse me, I am lost. Can you show me the way to the Egyptian Museum?", translation: "\u0644\u0648 \u0633\u0645\u062D\u062A\u060C \u0623\u0646\u0627 \u062A\u0627\u064A\u0647. \u0645\u0645\u0643\u0646 \u062A\u0648\u0631\u064A\u0646\u064A \u0627\u0644\u0637\u0631\u064A\u0642 \u0644\u0644\u0645\u062A\u062D\u0641 \u0627\u0644\u0645\u0635\u0631\u064A\u061F" },
            { speaker: "Local", text: "Sure! Go straight ahead past the train station, and turn left at the traffic light.", translation: "\u0623\u0643\u064A\u062F! \u0627\u0645\u0634\u064A \u0639\u0644\u0637\u0648\u0644 \u0648\u0639\u062F\u064A \u0645\u062D\u0637\u0629 \u0627\u0644\u0642\u0637\u0631\u060C \u0648\u0627\u062D\u0648\u062F \u0634\u0645\u0627\u0644 \u0639\u0646\u062F \u0625\u0634\u0627\u0631\u0629 \u0627\u0644\u0645\u0631\u0648\u0631." },
            { speaker: "Tourist", text: "Do I have to cross any bridge?", translation: "\u0647\u0648 \u0623\u0646\u0627 \u0644\u0627\u0632\u0645 \u0623\u0639\u062F\u064A \u0623\u064A \u0643\u0648\u0628\u0631\u064A\u061F" },
            { speaker: "Local", text: "No. The museum is on the corner of the next street, opposite the big hotel.", translation: "\u0644\u0627. \u0627\u0644\u0645\u062A\u062D\u0641 \u0639\u0644\u0649 \u0646\u0627\u0635\u064A\u0629 \u0627\u0644\u0634\u0627\u0631\u0639 \u0627\u0644\u062C\u0627\u064A\u060C \u0641\u064A \u0645\u0648\u0627\u062C\u0647\u0629 \u0627\u0644\u0641\u0646\u062F\u0642 \u0627\u0644\u0643\u0628\u064A\u0631." }
          ]
        },
        practice: {
          listening: [
            { text: "Turn left at the traffic light.", options: ["left", "right", "straight"], answer: "left", hint: "\u0639\u0643\u0633 \u0643\u0644\u0645\u0629 \u064A\u0645\u064A\u0646" },
            { text: "The museum is opposite the park.", options: ["opposite", "behind", "near"], answer: "opposite", hint: "\u0641\u064A \u0627\u0644\u062C\u0647\u0629 \u0627\u0644\u0645\u0642\u0627\u0628\u0644\u0629 \u0639\u0628\u0631 \u0627\u0644\u0634\u0627\u0631\u0639" },
            { text: "Go across the Nile bridge.", options: ["bridge", "roundabout", "station"], answer: "bridge", hint: "\u0627\u0644\u0645\u0628\u0646\u0649 \u0627\u0644\u0645\u0631\u062A\u0641\u0639 \u0627\u0644\u0645\u062E\u0635\u0635 \u0644\u0644\u0645\u0631\u0648\u0631 \u0641\u0648\u0642 \u0627\u0644\u0646\u0647\u0631" }
          ],
          speaking: [
            { text: "Can you give me directions", translation: "\u0647\u0644 \u064A\u0645\u0643\u0646\u0643 \u0625\u0639\u0637\u0627\u0626\u064A \u0627\u062A\u062C\u0627\u0647\u0627\u062A \u0627\u0644\u0637\u0631\u064A\u0642\u061F" },
            { text: "Where is the train station", translation: "\u0623\u064A\u0646 \u062A\u0642\u0639 \u0645\u062D\u0637\u0629 \u0627\u0644\u0642\u0637\u0627\u0631\u061F" }
          ],
          reading: {
            passage: "Cairo is a very large city, and tourists sometimes get lost. John is a tourist from England. He wants to visit the public library. He asks a local guide for directions. The guide says: 'Go straight down this street for two blocks. Cross the roundabout, and turn right. The library is next to the big supermarket, between the bank and the school.' John thanks the guide and finds the library easily.",
            questions: [
              { q: "Who does John ask for directions?", options: ["A local guide", "A policeman", "A driver"], answer: "A local guide", explanation: "\u064A\u0633\u0623\u0644 \u062C\u0648\u0646 \u0645\u0631\u0634\u062F\u0627\u064B \u0645\u062D\u0644\u064A\u0627\u064B \u0639\u0646 \u0627\u0644\u0627\u062A\u062C\u0627\u0647\u0627\u062A." },
              { q: "Where is the library located?", options: ["Between the bank and the school", "Behind the train station", "Opposite the hotel"], answer: "Between the bank and the school", explanation: "\u062A\u0642\u0639 \u0627\u0644\u0645\u0643\u062A\u0628\u0629 \u0628\u064A\u0646 \u0627\u0644\u0628\u0646\u0643 \u0648\u0627\u0644\u0645\u062F\u0631\u0633\u0629 \u0628\u062C\u0627\u0646\u0628 \u0627\u0644\u0633\u0648\u0628\u0631 \u0645\u0627\u0631\u0643\u062A." }
            ]
          },
          writing: [
            { prompt: "\u0631\u062A\u0628 \u0627\u0644\u0643\u0644\u0645\u0627\u062A: (\u0627\u0644\u0645\u062D\u0644 \u064A\u0642\u0639 \u0639\u0644\u0649 \u0627\u0644\u0646\u0627\u0635\u064A\u0629.)", words: ["corner / is / The / the / shop / on"], correct: ["The", "shop", "is", "on", "the", "corner"] },
            { prompt: "\u0623\u0643\u0645\u0644 \u0627\u0644\u0641\u0631\u0627\u063A: The bank is ___ the post office.", placeholder: "next to / between / across", answer: "next to" }
          ]
        }
      };
    }
  });

