          { id: 2199, word: "pilot", translation: "\u0637\u064A\u0627\u0631", example: "The pilot spoke to the passengers.", exampleTranslation: "\u0627\u0644\u0637\u064A\u0627\u0631 \u0627\u062A\u0643\u0644\u0645 \u0645\u0639 \u0627\u0644\u0631\u0643\u0627\u0628." },
          { id: 2200, word: "flight attendant", translation: "\u0645\u0636\u064A\u0641 / \u0645\u0636\u064A\u0641\u0629 \u0637\u064A\u0631\u0627\u0646", example: "Ask the flight attendant for water.", exampleTranslation: "\u0627\u0637\u0644\u0628 \u0645\u064A\u0629 \u0645\u0646 \u0645\u0636\u064A\u0641\u0629 \u0627\u0644\u0637\u064A\u0631\u0627\u0646." },
          { id: 2201, word: "baggage claim", translation: "\u0645\u0646\u0637\u0642\u0629 \u0627\u0633\u062A\u0644\u0627\u0645 \u0627\u0644\u0623\u0645\u062A\u0639\u0629", example: "Pick up bags at baggage claim.", exampleTranslation: "\u0627\u0633\u062A\u0644\u0645 \u0627\u0644\u0634\u0646\u0637 \u0645\u0646 \u0645\u0646\u0637\u0642\u0629 \u0627\u0633\u062A\u0644\u0627\u0645 \u0627\u0644\u062D\u0642\u0627\u0626\u0628." },
          { id: 2202, word: "duty-free", translation: "\u0627\u0644\u0633\u0648\u0642 \u0627\u0644\u062D\u0631\u0629", example: "Buy gifts at the duty-free shop.", exampleTranslation: "\u0627\u0634\u062A\u0631\u064A \u0647\u062F\u0627\u064A\u0627 \u0645\u0646 \u0645\u062D\u0644 \u0627\u0644\u0633\u0648\u0642 \u0627\u0644\u062D\u0631\u0629." },
          { id: 2203, word: "scale", translation: "\u0645\u064A\u0632\u0627\u0646 \u0627\u0644\u0623\u0645\u062A\u0639\u0629", example: "Put your suitcase on the scale.", exampleTranslation: "\u062D\u0637 \u0634\u0646\u0637\u062A\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u064A\u0632\u0627\u0646." },
          { id: 2204, word: "overweight", translation: "\u0648\u0632\u0646 \u0632\u0627\u0626\u062F", example: "Your baggage is overweight.", exampleTranslation: "\u0634\u0646\u0637\u062A\u0643 \u0648\u0632\u0646\u0647\u0627 \u0632\u0627\u064A\u062F." }
