  var lesson172;
  var init_lesson172 = __esm({
    "js/data/A2/units/unit5/lesson17.js"() {
      lesson172 = {
        id: 17,
        unitId: 5,
        title: "Jobs and Workplaces",
        description: "Learn career terminology, work environments, job tasks, and using the present perfect simple.",
        explanation: {
          intro: "\u0645\u0631\u062D\u0628\u0627\u064B \u0628\u0643 \u0641\u064A \u0627\u0644\u0648\u062D\u062F\u0629 \u0627\u0644\u062E\u0627\u0645\u0633\u0629! \u0633\u0646\u062A\u0639\u0644\u0645 \u0627\u0644\u064A\u0648\u0645 \u0645\u0641\u0631\u062F\u0627\u062A \u0627\u0644\u0645\u0647\u0646 \u0648\u0623\u0645\u0627\u0643\u0646 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0645\u062E\u062A\u0644\u0641\u0629\u060C \u0648\u0627\u0644\u062A\u062F\u0631\u0628 \u0639\u0644\u0649 \u0632\u0645\u0646 \u0627\u0644\u0645\u0636\u0627\u0631\u0639 \u0627\u0644\u062A\u0627\u0645 \u0627\u0644\u0628\u0633\u064A\u0637 \u0644\u0648\u0635\u0641 \u0627\u0644\u062E\u0628\u0631\u0627\u062A \u0648\u0627\u0644\u062A\u062C\u0627\u0631\u0628 \u0627\u0644\u062D\u064A\u0627\u062A\u064A\u0629 \u0648\u0627\u0644\u0645\u0647\u0646\u064A\u0629.",
          sections: [
            {
              title: "1. Present Perfect Simple (\u0632\u0645\u0646 \u0627\u0644\u0645\u0636\u0627\u0631\u0639 \u0627\u0644\u062A\u0627\u0645)",
              content: "\u0646\u0633\u062A\u062E\u062F\u0645 \u0627\u0644\u0645\u0636\u0627\u0631\u0639 \u0627\u0644\u062A\u0627\u0645 \u0644\u0644\u062D\u062F\u064A\u062B \u0639\u0646 \u0623\u062D\u062F\u0627\u062B \u0628\u062F\u0623\u062A \u0641\u064A \u0627\u0644\u0645\u0627\u0636\u064A \u0648\u0644\u0647\u0627 \u0635\u0644\u0629 \u0628\u0627\u0644\u0648\u0642\u062A \u0627\u0644\u062D\u0627\u0636\u0631\u060C \u0623\u0648 \u0644\u0644\u062A\u0639\u0628\u064A\u0631 \u0639\u0646 \u062A\u062C\u0627\u0631\u0628 \u062D\u064A\u0627\u062A\u064A\u0629 \u062F\u0648\u0646 \u062A\u062D\u062F\u064A\u062F \u0632\u0645\u0646 \u062D\u062F\u0648\u062B\u0647\u0627 \u0628\u062F\u0642\u0629:\n- **have** + \u0627\u0644\u062A\u0635\u0631\u064A\u0641 \u0627\u0644\u062B\u0627\u0644\u062B (\u0645\u0639 I, You, We, They): I **have worked** here for five years.\n- **has** + \u0627\u0644\u062A\u0635\u0631\u064A\u0641 \u0627\u0644\u062B\u0627\u0644\u062B (\u0645\u0639 He, She, It): She **has visited** the new factory."
            },
            {
              title: "2. Regular vs Irregular Participles (\u0627\u0644\u062A\u0635\u0631\u064A\u0641 \u0627\u0644\u062B\u0627\u0644\u062B \u0644\u0644\u0623\u0641\u0639\u0627\u0644)",
              content: "\u064A\u0646\u0642\u0633\u0645 \u0627\u0644\u062A\u0635\u0631\u064A\u0641 \u0627\u0644\u062B\u0627\u0644\u062B (Past Participle) \u0625\u0644\u0649 \u0642\u0633\u0645\u064A\u0646:\n- \u0623\u0641\u0639\u0627\u0644 \u0645\u0646\u062A\u0638\u0645\u0629 \u062A\u0646\u062A\u0647\u064A \u0628\u0640 -ed: worked, visited, played.\n- \u0623\u0641\u0639\u0627\u0644 \u063A\u064A\u0631 \u0645\u0646\u062A\u0638\u0645\u0629 \u062A\u062A\u063A\u064A\u0631 \u0628\u0627\u0644\u0643\u0627\u0645\u0644: been (\u0645\u0646 be), done (\u0645\u0646 do), written (\u0645\u0646 write), seen (\u0645\u0646 see)."
            }
          ]
        },
        vocabulary: [
          { id: 2467, word: "jobs", translation: "\u0648\u0638\u0627\u0626\u0641", example: "He applied for three jobs.", exampleTranslation: "\u0642\u062F\u0645 \u0639\u0644\u0649 \u062A\u0644\u0627\u062A \u0648\u0638\u0627\u0626\u0641." },
          { id: 2468, word: "career", translation: "\u0645\u0633\u0627\u0631 \u0645\u0647\u0646\u064A / \u0645\u0633\u062A\u0642\u0628\u0644 \u0639\u0645\u0644\u064A", example: "Teaching is a rewarding career.", exampleTranslation: "\u0627\u0644\u062A\u062F\u0631\u064A\u0633 \u0645\u0633\u0627\u0631 \u0645\u0647\u0646\u064A \u0645\u062C\u0632\u064A." },
          { id: 2469, word: "occupation", translation: "\u0645\u0647\u0646\u0629 / \u062D\u0631\u0641\u0629", example: "State your occupation on the form.", exampleTranslation: "\u0627\u0643\u062A\u0628 \u0645\u0647\u0646\u062A\u0643 \u0641\u064A \u0627\u0644\u0627\u0633\u062A\u0645\u0627\u0631\u0629." },
          { id: 2470, word: "workplace", translation: "\u0645\u0643\u0627\u0646 \u0627\u0644\u0639\u0645\u0644", example: "Our workplace is modern.", exampleTranslation: "\u0645\u0643\u0627\u0646 \u0627\u0644\u0634\u063A\u0644 \u0628\u062A\u0627\u0639\u0646\u0627 \u062D\u062F\u064A\u062B." },
          { id: 2471, word: "office", translation: "\u0645\u0643\u062A\u0628", example: "I work in an office.", exampleTranslation: "\u0628\u0634\u062A\u063A\u0644 \u0641\u064A \u0645\u0643\u062A\u0628." },
          { id: 2472, word: "factory", translation: "\u0645\u0635\u0646\u0639", example: "He works at a car factory.", exampleTranslation: "\u0634\u063A\u0627\u0644 \u0641\u064A \u0645\u0635\u0646\u0639 \u0639\u0631\u0628\u064A\u0627\u062A." },
          { id: 2473, word: "hospital", translation: "\u0645\u0633\u062A\u0634\u0641\u0649", example: "Nurses work in the hospital.", exampleTranslation: "\u0627\u0644\u0645\u0645\u0631\u0636\u0627\u062A \u0634\u063A\u0627\u0644\u064A\u0646 \u0641\u064A \u0627\u0644\u0645\u0633\u062A\u0634\u0641\u0649." },
          { id: 2474, word: "manager", translation: "\u0645\u062F\u064A\u0631", example: "The manager approved my vacation.", exampleTranslation: "\u0627\u0644\u0645\u062F\u064A\u0631 \u0648\u0627\u0641\u0642 \u0639\u0644\u0649 \u0627\u0644\u0625\u062C\u0627\u0632\u0629 \u0628\u062A\u0627\u0639\u062A\u064A." },
          { id: 2475, word: "employee", translation: "\u0645\u0648\u0638\u0641 / \u0639\u0627\u0645\u0644", example: "The company has forty employees.", exampleTranslation: "\u0627\u0644\u0634\u0631\u0643\u0629 \u0641\u064A\u0647\u0627 \u0623\u0631\u0628\u0639\u064A\u0646 \u0645\u0648\u0638\u0641." },
          { id: 2476, word: "employer", translation: "\u0635\u0627\u062D\u0628 \u0627\u0644\u0639\u0645\u0644 / \u0631\u0626\u064A\u0633 \u0627\u0644\u0639\u0645\u0644", example: "She is a kind employer.", exampleTranslation: "\u0647\u064A \u0635\u0627\u062D\u0628\u0629 \u0639\u0645\u0644 \u0637\u064A\u0628\u0629." },
          { id: 2477, word: "staff", translation: "\u0637\u0627\u0642\u0645 \u0627\u0644\u0639\u0645\u0644 / \u0627\u0644\u0645\u0648\u0638\u0641\u064A\u0646", example: "The hotel staff is friendly.", exampleTranslation: "\u0637\u0627\u0642\u0645 \u0639\u0645\u0644 \u0627\u0644\u0641\u0646\u062F\u0642 \u0648\u062F\u0648\u062F." },
          { id: 2478, word: "boss", translation: "\u0631\u0626\u064A\u0633 \u0627\u0644\u0639\u0645\u0644 / \u0627\u0644\u0645\u062F\u064A\u0631 (\u0639\u0627\u0645\u064A\u0629)", example: "The boss called a meeting.", exampleTranslation: "\u0627\u0644\u0645\u062F\u064A\u0631 \u0637\u0644\u0628 \u0627\u062C\u062A\u0645\u0627\u0639." },
          { id: 2479, word: "task", translation: "\u0645\u0647\u0645\u0629 \u0639\u0645\u0644", example: "Finish your daily tasks.", exampleTranslation: "\u062E\u0644\u0635 \u0645\u0647\u0627\u0645\u0643 \u0627\u0644\u064A\u0648\u0645\u064A\u0629." },
          { id: 2480, word: "duty", translation: "\u0648\u0627\u062C\u0628 \u0648\u0638\u064A\u0641\u064A", example: "It is my duty to help you.", exampleTranslation: "\u062F\u0627 \u0648\u0627\u062C\u0628\u064A \u0627\u0644\u0648\u0638\u064A\u0641\u064A \u0625\u0646\u064A \u0623\u0633\u0627\u0639\u062F\u0643." },
          { id: 2481, word: "salary", translation: "\u0645\u0631\u062A\u0628 \u0634\u0647\u0631\u064A", example: "My salary is paid monthly.", exampleTranslation: "\u0627\u0644\u0645\u0631\u062A\u0628 \u0628\u062A\u0627\u0639\u064A \u0628\u064A\u062A\u062F\u0641\u0639 \u0634\u0647\u0631\u064A\u0627\u064B." },
          { id: 2482, word: "income", translation: "\u062F\u062E\u0644 \u0645\u0627\u0644\u064A", example: "He wants to increase his income.", exampleTranslation: "\u0639\u0627\u064A\u0632 \u064A\u0632\u0648\u062F \u062F\u062E\u0644\u0647." },
          { id: 2483, word: "hour", translation: "\u0633\u0627\u0639\u0629 \u0632\u0645\u0646\u064A\u0629", example: "I work eight hours a day.", exampleTranslation: "\u0628\u0634\u062A\u063A\u0644 \u062A\u0645\u0627\u0646 \u0633\u0627\u0639\u0627\u062A \u0641\u064A \u0627\u0644\u064A\u0648\u0645." },
          { id: 2484, word: "shift", translation: "\u0648\u0631\u062F\u064A\u0629 \u0627\u0644\u0639\u0645\u0644", example: "I prefer the morning shift.", exampleTranslation: "\u0628\u0641\u0636\u0644 \u0627\u0644\u0648\u0631\u062F\u064A\u0629 \u0627\u0644\u0635\u0628\u0627\u062D\u064A\u0629." },
          { id: 2485, word: "overtime", translation: "\u0639\u0645\u0644 \u0625\u0636\u0627\u0641\u064A / \u0633\u0627\u0639\u0627\u062A \u0639\u0645\u0644 \u0632\u0627\u0626\u062F\u0629", example: "He worked overtime last week.", exampleTranslation: "\u0627\u0634\u062A\u063A\u0644 \u0648\u0642\u062A \u0625\u0636\u0627\u0641\u064A \u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u0644\u064A \u0641\u0627\u062A." },
          { id: 2486, word: "hire", translation: "\u064A\u0648\u0638\u0641 / \u064A\u0634\u063A\u0651\u0644", example: "The bank will hire new clerks.", exampleTranslation: "\u0627\u0644\u0628\u0646\u0643 \u0647\u064A\u0648\u0638\u0641 \u0645\u0648\u0638\u0641\u064A\u0646 \u062C\u062F\u0627\u062F." },
          { id: 2487, word: "fire", translation: "\u064A\u0637\u0631\u062F \u0645\u0646 \u0627\u0644\u0639\u0645\u0644 / \u064A\u0641\u0635\u0644", example: "Do not violate the rules or they will fire you.", exampleTranslation: "\u0645\u0627\u062A\u062E\u0627\u0644\u0641\u0634 \u0627\u0644\u0642\u0648\u0627\u0639\u062F \u0648\u0625\u0644\u0627 \u0647\u064A\u0637\u0631\u062F\u0648\u0643 \u0645\u0646 \u0627\u0644\u0634\u063A\u0644." },
          { id: 2488, word: "retire", translation: "\u064A\u062A\u0642\u0627\u0639\u062F \u0639\u0646 \u0627\u0644\u0639\u0645\u0644 \u0639\u0646\u062F \u0643\u0628\u0631 \u0627\u0644\u0633\u0646", example: "My father will retire next year.", exampleTranslation: "\u0623\u0628\u0648\u064A\u0627 \u0647\u064A\u062A\u0642\u0627\u0639\u062F \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u062C\u0627\u064A\u0629." },
          { id: 2489, word: "apply", translation: "\u064A\u0642\u062F\u0645 \u0637\u0644\u0628 (\u0648\u0638\u064A\u0641\u0629 \u0623\u0648 \u0641\u064A\u0632\u0627)", example: "Apply online for the job.", exampleTranslation: "\u0642\u062F\u0645 \u0639\u0644\u0649 \u0627\u0644\u0648\u0638\u064A\u0641\u0629 \u0623\u0648\u0646\u0644\u0627\u064A\u0646." },
          { id: 2490, word: "interview", translation: "\u0645\u0642\u0627\u0628\u0644\u0629 \u0639\u0645\u0644 / \u062D\u0648\u0627\u0631", example: "My job interview was successful.", exampleTranslation: "\u0645\u0642\u0627\u0628\u0644\u0629 \u0627\u0644\u0634\u063A\u0644 \u0628\u062A\u0627\u0639\u062A\u064A \u0643\u0627\u0646\u062A \u0646\u0627\u062C\u062D\u0629." },
          { id: 2491, word: "qualify", translation: "\u064A\u062A\u0623\u0647\u0644 / \u064A\u0635\u0628\u062D \u0645\u0624\u0647\u0644\u0627\u064B", example: "This course will qualify you for the job.", exampleTranslation: "\u0627\u0644\u0643\u0648\u0631\u0633 \u062F\u0647 \u0647\u064A\u0623\u0647\u0644\u0643 \u0644\u0644\u0648\u0638\u064A\u0641\u0629." },
          { id: 2492, word: "experience", translation: "\u062E\u0628\u0631\u0629 \u0639\u0645\u0644\u064A\u0629 / \u062A\u062C\u0631\u0628\u0629", example: "Do you have any sales experience?", exampleTranslation: "\u0647\u0644 \u0639\u0646\u062F\u0643 \u0623\u064A \u062E\u0628\u0631\u0629 \u0641\u064A \u0627\u0644\u0645\u0628\u064A\u0639\u0627\u062A\u061F" },
          { id: 2493, word: "business", translation: "\u062A\u062C\u0627\u0631\u0629 / \u0623\u0639\u0645\u0627\u0644 / \u0634\u0631\u0643\u0629", example: "She owns a small business.", exampleTranslation: "\u0647\u064A \u0628\u062A\u0645\u0644\u0643 \u0639\u0645\u0644 \u062A\u062C\u0627\u0631\u064A \u0635\u063A\u064A\u0631." },
          { id: 2494, word: "earn", translation: "\u064A\u0643\u062A\u0633\u0628 / \u064A\u062C\u0646\u064A \u0645\u0627\u0644\u0627\u064B", example: "How much does a doctor earn?", exampleTranslation: "\u0627\u0644\u062F\u0643\u062A\u0648\u0631 \u0628\u064A\u0643\u0633\u0628 \u0643\u0627\u0645\u061F" },
          { id: 2495, word: "meeting", translation: "\u0627\u062C\u062A\u0645\u0627\u0639", example: "We have a staff meeting.", exampleTranslation: "\u0639\u0646\u062F\u0646\u0627 \u0627\u062C\u062A\u0645\u0627\u0639 \u0645\u0648\u0638\u0641\u064A\u0646." },
          { id: 2496, word: "office worker", translation: "\u0645\u0648\u0638\u0641 \u0645\u0643\u062A\u0628", example: "Office workers sit for long hours.", exampleTranslation: "\u0645\u0648\u0638\u0641\u064A\u0646 \u0627\u0644\u0645\u0643\u0627\u062A\u0628 \u0628\u064A\u0642\u0639\u062F\u0648\u0627 \u0644\u0633\u0627\u0639\u0627\u062A \u0637\u0648\u064A\u0644\u0629." }
        ],
        dialogue: {
          title: "Discussing Career Experiences",
          lines: [
            { speaker: "Adel", text: "How long have you worked at this hospital, Sarah?", translation: "\u0628\u0642\u0627\u0644\u0643 \u0642\u062F \u0625\u064A\u0647 \u0634\u063A\u0627\u0644\u0629 \u0641\u064A \u0627\u0644\u0645\u0633\u062A\u0634\u0641\u0649 \u062F\u064A \u064A\u0627 \u0633\u0627\u0631\u0629\u061F" },
            { speaker: "Sarah", text: "I have worked here as a nurse for three years now. It is a busy workplace.", translation: "\u0634\u063A\u0627\u0644\u0629 \u0647\u0646\u0627 \u0645\u0645\u0631\u0636\u0629 \u0628\u0642\u0627\u0644\u064A \u062A\u0644\u0627\u062A \u0633\u0646\u064A\u0646 \u062F\u0644\u0648\u0642\u062A\u064A. \u0647\u0648 \u0645\u0643\u0627\u0646 \u0634\u063A\u0644 \u0632\u062D\u0645\u0629 \u0648\u0645\u0634\u063A\u0648\u0644 \u062C\u062F\u0627\u064B." },
            { speaker: "Adel", text: "Have you ever met the new hospital manager?", translation: "\u0647\u0644 \u0642\u0627\u0628\u0644\u062A\u064A \u0645\u062F\u064A\u0631 \u0627\u0644\u0645\u0633\u062A\u0634\u0641\u0649 \u0627\u0644\u062C\u062F\u064A\u062F \u0642\u0628\u0644 \u0643\u062F\u0647\u061F" },
            { speaker: "Sarah", text: "Yes, I have. He has introduced new schedules for the staff shift.", translation: "\u0623\u0647 \u0642\u0627\u0628\u0644\u062A\u0647. \u0647\u0648 \u0642\u062F\u0645 \u062C\u062F\u0627\u0648\u0644 \u0645\u0648\u0627\u0639\u064A\u062F \u062C\u062F\u064A\u062F\u0629 \u0644\u0648\u0631\u062F\u064A\u0627\u062A \u0627\u0644\u0645\u0648\u0638\u0641\u064A\u0646." }
          ]
        },
        practice: {
          listening: [
            { text: "I have worked here for five years.", options: ["worked", "slept", "played"], answer: "worked", hint: "\u0627\u0644\u062A\u0635\u0631\u064A\u0641 \u0627\u0644\u062B\u0627\u0644\u062B \u0645\u0646 \u0627\u0644\u0641\u0639\u0644 \u064A\u0639\u0645\u0644 (work)" },
            { text: "The hospital is very modern.", options: ["hospital", "factory", "office"], answer: "hospital", hint: "\u0627\u0644\u0645\u0628\u0646\u0649 \u0627\u0644\u0645\u062E\u0635\u0635 \u0644\u062A\u0642\u062F\u064A\u0645 \u0627\u0644\u062E\u062F\u0645\u0627\u062A \u0627\u0644\u0637\u0628\u064A\u0629 \u0648\u0639\u0644\u0627\u062C \u0627\u0644\u0645\u0631\u0636\u0649" },
            { text: "The staff is very friendly.", options: ["staff", "boss", "customer"], answer: "staff", hint: "\u0645\u062C\u0645\u0648\u0639\u0629 \u0627\u0644\u0645\u0648\u0638\u0641\u064A\u0646 \u0648\u0627\u0644\u0639\u0627\u0645\u0644\u064A\u0646 \u062F\u0627\u062E\u0644 \u0627\u0644\u0645\u0624\u0633\u0633\u0629" }
          ],
          speaking: [
            { text: "Teaching is a rewarding career", translation: "\u0627\u0644\u062A\u062F\u0631\u064A\u0633 \u0645\u0633\u0627\u0631 \u0645\u0647\u0646\u064A \u0645\u062C\u0632\u064D." },
            { text: "I work in an office", translation: "\u0623\u0646\u0627 \u0623\u0639\u0645\u0644 \u0641\u064A \u0645\u0643\u062A\u0628." }
          ],
          reading: {
            passage: "Tamer is an office worker at a large computer company in Cairo. He has had a successful career. He has worked at this company since 2023. Tamer's employer is a kind manager who values the staff. Tamer's daily tasks include writing reports and attending staff meetings. He has recently applied for a higher position. He has already passed the interview, and the boss has decided to hire him next month.",
            questions: [
              { q: "How long has Tamer worked at the computer company?", options: ["Since 2023", "For ten years", "For one month"], answer: "Since 2023", explanation: "\u064A\u0639\u0645\u0644 \u062A\u0627\u0645\u0631 \u0641\u064A \u0627\u0644\u0634\u0631\u0643\u0629 \u0645\u0646\u0630 \u0639\u0627\u0645 2023." },
              { q: "What did the boss decide to do next month?", options: ["Hire him for a higher position", "Fire him from the company", "Close the office"], answer: "Hire him for a higher position", explanation: "\u0642\u0631\u0631 \u0631\u0626\u064A\u0633 \u0627\u0644\u0639\u0645\u0644 \u062A\u0631\u0642\u064A\u062A\u0647 \u0648\u062A\u0648\u0638\u064A\u0641\u0647 \u0641\u064A \u0645\u0646\u0635\u0628 \u0623\u0639\u0644\u0649 \u0627\u0644\u0634\u0647\u0631 \u0627\u0644\u0645\u0642\u0628\u0644." }
            ]
          },
          writing: [
            { prompt: "\u0631\u062A\u0628 \u0627\u0644\u0643\u0644\u0645\u0627\u062A: (\u0647\u064A \u0632\u0627\u0631\u062A \u0627\u0644\u0645\u0635\u0646\u0639 \u0627\u0644\u062C\u062F\u064A\u062F.)", words: ["factory / has / new / She / visited / the"], correct: ["She", "has", "visited", "the", "new", "factory"] },
            { prompt: "\u0623\u0643\u0645\u0644 \u0627\u0644\u0641\u0631\u0627\u063A: We ___ never been to London.", placeholder: "has / have / did", answer: "have" }
          ]
        }
      };
    }
  });

  // js/data/A2/units/unit5/lesson18.js
  var lesson182;
  var init_lesson182 = __esm({
    "js/data/A2/units/unit5/lesson18.js"() {
      lesson182 = {
        id: 18,
        unitId: 5,
        title: "Job Applications and Interviews",
        description: "Learn CV terminology, interview preparation, strengths/weaknesses, and comparing present perfect with past simple.",
        explanation: {
          intro: "\u0623\u0647\u0644\u0627\u064B \u0628\u0643 \u0641\u064A \u0627\u0644\u062F\u0631\u0633 \u0627\u0644\u062B\u0627\u0645\u0646 \u0639\u0634\u0631! \u0633\u0646\u062A\u0639\u0644\u0645 \u0627\u0644\u064A\u0648\u0645 \u0643\u064A\u0641\u064A\u0629 \u0643\u062A\u0627\u0628\u0629 \u0627\u0644\u0633\u064A\u0631\u0629 \u0627\u0644\u0630\u0627\u062A\u064A\u0629 (CV)\u060C \u0648\u0627\u0644\u062A\u062D\u0636\u064A\u0631 \u0644\u0645\u0642\u0627\u0628\u0644\u0627\u062A \u0627\u0644\u0639\u0645\u0644\u060C \u0648\u0627\u0644\u0641\u0631\u0642 \u0627\u0644\u0647\u0627\u0645 \u062C\u062F\u0627\u064B \u0641\u064A \u0627\u0644\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0628\u064A\u0646 \u0632\u0645\u0646\u064A \u0627\u0644\u0645\u0636\u0627\u0631\u0639 \u0627\u0644\u062A\u0627\u0645 \u0648\u0627\u0644\u0645\u0627\u0636\u064A \u0627\u0644\u0628\u0633\u064A\u0637 \u0639\u0646\u062F \u0627\u0644\u062D\u062F\u064A\u062B \u0639\u0646 \u062E\u0628\u0631\u0627\u062A\u0643 \u0648\u062A\u0627\u0631\u064A\u062E\u0643 \u0627\u0644\u0648\u0638\u064A\u0641\u064A.",
          sections: [
            {
              title: "1. Present Perfect vs Past Simple (\u0627\u0644\u0645\u0636\u0627\u0631\u0639 \u0627\u0644\u062A\u0627\u0645 \u0645\u0642\u0627\u0628\u0644 \u0627\u0644\u0645\u0627\u0636\u064A \u0627\u0644\u0628\u0633\u064A\u0637)",
              content: "\u0627\u0644\u0641\u0631\u0642 \u0627\u0644\u0623\u0633\u0627\u0633\u064A \u064A\u0639\u062A\u0645\u062F \u0639\u0644\u0649 \u062A\u062D\u062F\u064A\u062F \u0648\u0642\u062A \u062D\u062F\u0648\u062B \u0627\u0644\u0641\u0639\u0644:\n- \u0646\u0633\u062A\u062E\u062F\u0645 **Present Perfect** \u0644\u0644\u062D\u062F\u064A\u062B \u0639\u0646 \u062E\u0628\u0631\u0629 \u0639\u0627\u0645\u0629 \u0628\u062F\u0648\u0646 \u0630\u0643\u0631 \u0645\u062A\u0649 \u062D\u062F\u062B\u062A: I **have written** many reports. (\u0644\u0627 \u0646\u062D\u062F\u062F \u0645\u062A\u0649).\n- \u0646\u0633\u062A\u062E\u062F\u0645 **Past Simple** \u0644\u0644\u062D\u062F\u064A\u062B \u0639\u0646 \u062D\u062F\u062B \u0627\u0646\u062A\u0647\u0649 \u062A\u0645\u0627\u0645\u0627\u064B \u0648\u062A\u0645 \u062A\u062D\u062F\u064A\u062F \u0632\u0645\u0646\u0647 \u0628\u062F\u0642\u0629: I **wrote** a report **yesterday** / I **sent** my CV **last Monday**."
            },
            {
              title: "2. Common Interview Phrases (\u0635\u064A\u063A \u0634\u0627\u0626\u0639\u0629 \u0641\u064A \u0645\u0642\u0627\u0628\u0644\u0629 \u0627\u0644\u0639\u0645\u0644)",
              content: "\u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u0645\u0642\u0627\u0628\u0644\u0629 \u0627\u0644\u0634\u062E\u0635\u064A\u0629:\n- \u0644\u0644\u062D\u062F\u064A\u062B \u0639\u0646 \u0627\u0644\u062A\u0639\u0644\u064A\u0645 \u0648\u0627\u0644\u0634\u0647\u0627\u062F\u0627\u062A: I graduated from Cairo University in 2024 (Past Simple).\n- \u0644\u0644\u062D\u062F\u064A\u062B \u0639\u0646 \u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062A \u0627\u0644\u062D\u0627\u0644\u064A\u0629: I am fluent in English, and I have good communication skills."
            }
          ]
        },
        vocabulary: [
          { id: 2497, word: "application", translation: "\u0637\u0644\u0628 \u062A\u0642\u062F\u064A\u0645 (\u0644\u0648\u0638\u064A\u0641\u0629 \u0623\u0648 \u062C\u0627\u0645\u0639\u0629)", example: "Submit your job application.", exampleTranslation: "\u0642\u062F\u0645 \u0637\u0644\u0628 \u0627\u0644\u0648\u0638\u064A\u0641\u0629 \u0628\u062A\u0627\u0639\u0643." },
          { id: 2498, word: "form", translation: "\u0627\u0633\u062A\u0645\u0627\u0631\u0629 / \u0646\u0645\u0648\u0630\u062C", example: "Fill in the application form.", exampleTranslation: "\u0627\u0645\u0644\u0623 \u0627\u0633\u062A\u0645\u0627\u0631\u0629 \u0627\u0644\u062A\u0642\u062F\u064A\u0645." },
          { id: 2499, word: "apply", translation: "\u064A\u0642\u062F\u0645 \u0637\u0644\u0628", example: "I want to apply for this position.", exampleTranslation: "\u0639\u0627\u064A\u0632 \u0623\u0642\u062F\u0645 \u0639\u0644\u0649 \u0627\u0644\u0645\u0646\u0635\u0628 \u062F\u0647." },
          { id: 2500, word: "resume", translation: "\u0633\u064A\u0631\u0629 \u0630\u0627\u062A\u064A\u0629 \u0645\u0644\u062E\u0635\u0629", example: "Send your resume by email.", exampleTranslation: "\u0627\u0628\u0639\u062A \u0633\u064A\u0631\u062A\u0643 \u0627\u0644\u0630\u0627\u062A\u064A\u0629 \u0628\u0627\u0644\u0625\u064A\u0645\u064A\u0644." },
          { id: 2501, word: "CV", translation: "\u0633\u064A\u0631\u0629 \u0630\u0627\u062A\u064A\u0629 \u062A\u0641\u0635\u064A\u0644\u064A\u0629", example: "My CV includes my work experience.", exampleTranslation: "\u0627\u0644\u0633\u064A\u0631\u0629 \u0627\u0644\u0630\u0627\u062A\u064A\u0629 \u0628\u062A\u0627\u0639\u062A\u064A \u0628\u062A\u0634\u0645\u0644 \u062E\u0628\u0631\u062A\u064A \u0641\u064A \u0627\u0644\u0634\u063A\u0644." },
          { id: 2502, word: "reference", translation: "\u0645\u0631\u062C\u0639 / \u0634\u062E\u0635 \u0644\u0644\u062A\u0648\u0635\u064A\u0629", example: "List two professional references.", exampleTranslation: "\u0627\u0643\u062A\u0628 \u0627\u062A\u0646\u064A\u0646 \u0645\u0646 \u0645\u0639\u0631\u0641\u064A\u0646\u0643 \u0627\u0644\u0645\u0647\u0646\u064A\u064A\u0646 \u0644\u0644\u062A\u0648\u0635\u064A\u0629." },
          { id: 2503, word: "skill", translation: "\u0645\u0647\u0627\u0631\u0629", example: "Computer skills are necessary.", exampleTranslation: "\u0645\u0647\u0627\u0631\u0627\u062A \u0627\u0644\u0643\u0645\u0628\u064A\u0648\u062A\u0631 \u0636\u0631\u0648\u0631\u064A\u0629." },
          { id: 2504, word: "language", translation: "\u0644\u063A\u0629", example: "I speak two languages.", exampleTranslation: "\u0628\u062A\u0643\u0644\u0645 \u0644\u063A\u062A\u064A\u0646." },
          { id: 2505, word: "fluent", translation: "\u0637\u0644\u0627\u0642\u0629 \u0641\u064A \u0627\u0644\u0643\u0644\u0627\u0645 / \u0641\u0635\u064A\u062D", example: "She is fluent in English.", exampleTranslation: "\u0647\u064A \u0628\u062A\u062A\u0643\u0628 \u0625\u0646\u062C\u0644\u064A\u0632\u064A \u0628\u0637\u0644\u0627\u0642\u0629." },
          { id: 2506, word: "communication", translation: "\u0627\u062A\u0635\u0627\u0644 / \u062A\u0648\u0627\u0635\u0644", example: "He has excellent communication skills.", exampleTranslation: "\u0639\u0646\u062F\u0647 \u0645\u0647\u0627\u0631\u0627\u062A \u062A\u0648\u0627\u0635\u0644 \u0645\u0645\u062A\u0627\u0632\u0629." },
          { id: 2507, word: "team", translation: "\u0641\u0631\u064A\u0642", example: "I like working in a team.", exampleTranslation: "\u0628\u062D\u0628 \u0623\u0634\u062A\u063A\u0644 \u0641\u064A \u0641\u0631\u064A\u0642." },
          { id: 2508, word: "department", translation: "\u0642\u0633\u0645 \u0641\u064A \u0634\u0631\u0643\u0629 / \u0625\u062F\u0627\u0631\u0629", example: "He is in the marketing department.", exampleTranslation: "\u0647\u0648 \u0641\u064A \u0642\u0633\u0645 \u0627\u0644\u062A\u0633\u0648\u064A\u0642." },
          { id: 2509, word: "human resources", translation: "\u0627\u0644\u0645\u0648\u0627\u0631\u062F \u0627\u0644\u0628\u0634\u0631\u064A\u0629", example: "Send your documents to Human Resources.", exampleTranslation: "\u0627\u0628\u0639\u062A \u0623\u0648\u0631\u0627\u0642\u0643 \u0644\u0625\u062F\u0627\u0631\u0629 \u0627\u0644\u0645\u0648\u0627\u0631\u062F \u0627\u0644\u0628\u0634\u0631\u064A\u0629." },
          { id: 2510, word: "HR", translation: "\u0627\u0644\u0645\u0648\u0627\u0631\u062F \u0627\u0644\u0628\u0634\u0631\u064A\u0629 (\u0627\u062E\u062A\u0635\u0627\u0631)", example: "The HR manager called me.", exampleTranslation: "\u0645\u062F\u064A\u0631 \u0627\u0644\u0640 HR \u0643\u0644\u0645\u0646\u064A." },
          { id: 2511, word: "interviewer", translation: "\u0627\u0644\u0634\u062E\u0635 \u0627\u0644\u0630\u064A \u064A\u062C\u0631\u064A \u0627\u0644\u0645\u0642\u0627\u0628\u0644\u0629", example: "The interviewer asked hard questions.", exampleTranslation: "\u0627\u0644\u0644\u064A \u0628\u064A\u0639\u0645\u0644 \u0627\u0644\u0645\u0642\u0627\u0628\u0644\u0629 \u0633\u0623\u0644 \u0623\u0633\u0626\u0644\u0629 \u0635\u0639\u0628\u0629." },
          { id: 2512, word: "interviewee", translation: "\u0627\u0644\u0645\u062A\u0642\u062F\u0645 \u0644\u0644\u0645\u0642\u0627\u0628\u0644\u0629 / \u0627\u0644\u0645\u0631\u0634\u062D", example: "The interviewee answered confidently.", exampleTranslation: "\u0627\u0644\u0645\u0631\u0634\u062D \u062C\u0627\u0648\u0628 \u0628\u062B\u0642\u0629." },
          { id: 2513, word: "question", translation: "\u0633\u0624\u0627\u0644", example: "Answer every question carefully.", exampleTranslation: "\u062C\u0627\u0648\u0628 \u0639\u0644\u0649 \u0643\u0644 \u0633\u0624\u0627\u0644 \u0628\u062D\u0631\u0635." },
          { id: 2514, word: "answer", translation: "\u0625\u062C\u0627\u0628\u0629 / \u064A\u062C\u064A\u0628", example: "I do not know the answer.", exampleTranslation: "\u0645\u0634 \u0639\u0627\u0631\u0641 \u0627\u0644\u0625\u062C\u0627\u0628\u0629." },
          { id: 2515, word: "strengths", translation: "\u0646\u0642\u0627\u0637 \u0627\u0644\u0642\u0648\u0629", example: "What are your main strengths?", exampleTranslation: "\u0625\u064A\u0647 \u0647\u064A \u0623\u0647\u0645 \u0646\u0642\u0627\u0637 \u0642\u0648\u062A\u0643\u061F" },
          { id: 2516, word: "weaknesses", translation: "\u0646\u0642\u0627\u0637 \u0627\u0644\u0636\u0639\u0641", example: "Describe your weaknesses honestly.", exampleTranslation: "\u0627\u0648\u0635\u0641 \u0646\u0642\u0627\u0637 \u0636\u0639\u0641\u0643 \u0628\u0623\u0645\u0627\u0646\u0629." },
          { id: 2517, word: "goal", translation: "\u0647\u062F\u0641", example: "My goal is to learn coding.", exampleTranslation: "\u0647\u062F\u0641\u064A \u0625\u0646\u064A \u0623\u062A\u0639\u0644\u0645 \u0627\u0644\u0628\u0631\u0645\u062C\u0629." },
          { id: 2518, word: "achieve", translation: "\u064A\u062D\u0642\u0642 / \u064A\u0646\u062C\u0632", example: "Work hard to achieve your goals.", exampleTranslation: "\u0627\u062A\u0639\u0628 \u0639\u0634\u0627\u0646 \u062A\u062D\u0642\u0642 \u0623\u0647\u062F\u0627\u0641\u0643." },
          { id: 2519, word: "background", translation: "\u062E\u0644\u0641\u064A\u0629 \u0645\u0639\u0631\u0641\u064A\u0629 / \u062A\u0627\u0631\u064A\u062E \u0634\u062E\u0635\u064A", example: "I have a strong background in sales.", exampleTranslation: "\u0639\u0646\u062F\u064A \u062E\u0644\u0641\u064A\u0629 \u0642\u0648\u064A\u0629 \u0641\u064A \u0627\u0644\u0645\u0628\u064A\u0639\u0627\u062A." },
          { id: 2520, word: "education", translation: "\u062A\u0639\u0644\u064A\u0645 / \u062F\u0631\u0627\u0633\u0629", example: "My education is in computer science.", exampleTranslation: "\u062A\u0639\u0644\u064A\u0645\u064A \u0648\u062F\u0631\u0627\u0633\u062A\u064A \u0641\u064A \u0639\u0644\u0648\u0645 \u0627\u0644\u0643\u0645\u0628\u064A\u0648\u062A\u0631." },
          { id: 2521, word: "salary package", translation: "\u0627\u0644\u062D\u0632\u0645\u0629 \u0627\u0644\u0645\u0627\u0644\u064A\u0629 \u0627\u0644\u0643\u0644\u064A\u0629 \u0644\u0644\u0631\u0627\u062A\u0628", example: "They offered a good salary package.", exampleTranslation: "\u0639\u0631\u0636\u0648\u0627 \u062D\u0632\u0645\u0629 \u0631\u0627\u062A\u0628 \u0643\u0648\u064A\u0633\u0629." },
          { id: 2522, word: "offer", translation: "\u0639\u0631\u0636 / \u064A\u0639\u0631\u0636", example: "I accepted the job offer.", exampleTranslation: "\u0642\u0628\u0644\u062A \u0639\u0631\u0636 \u0627\u0644\u0634\u063A\u0644." },
          { id: 2523, word: "accept", translation: "\u064A\u0642\u0628\u0644", example: "We are happy to accept your application.", exampleTranslation: "\u0633\u0639\u062F\u0627\u0621 \u0628\u0642\u0628\u0648\u0644 \u0637\u0644\u0628\u0643." },
          { id: 2524, word: "reject", translation: "\u064A\u0631\u0641\u0636", example: "They rejected the offer.", exampleTranslation: "\u0631\u0641\u0636\u0648\u0627 \u0627\u0644\u0639\u0631\u0636." },
          { id: 2525, word: "sign", translation: "\u064A\u0648\u0642\u0639 / \u064A\u0645\u0636\u064A", example: "Please sign the contract.", exampleTranslation: "\u0627\u0645\u0636\u064A \u0627\u0644\u0639\u0642\u062F \u0644\u0648 \u0633\u0645\u062D\u062A." },
          { id: 2526, word: "contract", translation: "\u0639\u0642\u062F \u0639\u0645\u0644", example: "I signed a two-year contract.", exampleTranslation: "\u0648\u0642\u0639\u062A \u0639\u0642\u062F \u0645\u062F\u062A\u0647 \u0633\u0646\u062A\u064A\u0646." }
        ],
        dialogue: {
          title: "Job Interview at a Tech Company",
          lines: [
            { speaker: "Interviewer", text: "Welcome. I have reviewed your CV. You graduated in computer science, right?", translation: "\u0645\u0631\u062D\u0628\u0627\u064B \u0628\u0643. \u0644\u0642\u062F \u0631\u0627\u062C\u0639\u062A \u0633\u064A\u0631\u062A\u0643 \u0627\u0644\u0630\u0627\u062A\u064A\u0629. \u0644\u0642\u062F \u062A\u062E\u0631\u062C\u062A \u0641\u064A \u0639\u0644\u0648\u0645 \u0627\u0644\u062D\u0627\u0633\u0628\u060C \u0623\u0644\u064A\u0633 \u0643\u0630\u0644\u0643\u061F" },
            { speaker: "Interviewee", text: "Yes, I graduated from Cairo University in 2024. I have built three mobile apps since then.", translation: "\u0646\u0639\u0645\u060C \u062A\u062E\u0631\u062C\u062A \u0645\u0646 \u062C\u0627\u0645\u0639\u0629 \u0627\u0644\u0642\u0627\u0647\u0631\u0629 \u0639\u0627\u0645 2024. \u0648\u0642\u0645\u062A \u0628\u0628\u0646\u0627\u0621 \u062B\u0644\u0627\u062B\u0629 \u062A\u0637\u0628\u064A\u0642\u0627\u062A \u0647\u0648\u0627\u062A\u0641 \u0645\u0646\u0630 \u0630\u0644\u0643 \u0627\u0644\u062D\u064A\u0646." },
            { speaker: "Interviewer", text: "Excellent. Have you ever worked in a big team before?", translation: "\u0645\u0645\u062A\u0627\u0632. \u0647\u0644 \u0639\u0645\u0644\u062A \u0641\u064A \u0641\u0631\u064A\u0642 \u0643\u0628\u064A\u0631 \u0645\u0646 \u0642\u0628\u0644\u061F" },
            { speaker: "Interviewee", text: "Yes, I have. Last year, I worked with a team of five developers to deliver a project on time.", translation: "\u0646\u0639\u0645\u060C \u0639\u0645\u0644\u062A. \u0627\u0644\u0639\u0627\u0645 \u0627\u0644\u0645\u0627\u0636\u064A\u060C \u0639\u0645\u0644\u062A \u0645\u0639 \u0641\u0631\u064A\u0642 \u0645\u0643\u0648\u0646 \u0645\u0646 \u062E\u0645\u0633\u0629 \u0645\u0637\u0648\u0631\u064A\u0646 \u0644\u062A\u0633\u0644\u064A\u0645 \u0645\u0634\u0631\u0648\u0639 \u0641\u064A \u0627\u0644\u0648\u0642\u062A \u0627\u0644\u0645\u062D\u062F\u062F." }
          ]
        },
        practice: {
          listening: [
            { text: "I accepted the job offer.", options: ["accepted", "rejected", "signed"], answer: "accepted", hint: "\u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0629 \u0648\u0627\u0644\u0642\u0628\u0648\u0644 \u0644\u0644\u0634\u064A\u0621 \u0627\u0644\u0645\u0639\u0631\u0648\u0636" },
            { text: "My CV includes my work experience.", options: ["CV", "card", "letter"], answer: "CV", hint: "\u0627\u0644\u0648\u062B\u064A\u0642\u0629 \u0627\u0644\u0645\u0641\u0635\u0644\u0629 \u0627\u0644\u062A\u064A \u062A\u062D\u062A\u0648\u064A \u0639\u0644\u0649 \u062A\u0627\u0631\u064A\u062E\u0643 \u0627\u0644\u062A\u0639\u0644\u064A\u0645\u064A \u0648\u0627\u0644\u0645\u0647\u0646\u064A" },
            { text: "He is fluent in English.", options: ["fluent", "weak", "slow"], answer: "fluent", hint: "\u0627\u0644\u062A\u062D\u062F\u062B \u0628\u0644\u063A\u0629 \u0623\u062C\u0646\u0628\u064A\u0629 \u0628\u0637\u0644\u0627\u0642\u0629 \u0648\u0641\u0635\u0627\u062D\u0629 \u062A\u0627\u0645\u0629" }
          ],
          speaking: [
            { text: "Submit your job application", translation: "\u0642\u062F\u0651\u0645 \u0637\u0644\u0628 \u0627\u0644\u062A\u0642\u062F\u064A\u0645 \u0639\u0644\u0649 \u0627\u0644\u0648\u0638\u064A\u0641\u0629." },
            { text: "What are your main strengths", translation: "\u0645\u0627 \u0647\u064A \u0646\u0642\u0627\u0637 \u0642\u0648\u062A\u0643 \u0627\u0644\u0631\u0626\u064A\u0633\u064A\u0629\u061F" }
          ],
          reading: {
            passage: "Last week, Sarah applied for a marketing job at a large department store. She sent her CV and a cover letter to the HR department. Yesterday, she had an interview with the department manager. During the interview, Sarah discussed her background, education, and language skills. She explained that she is fluent in English and French. The interviewer was surprised by her experience. Today, they sent Sarah a job offer, and she is going to sign the contract tomorrow.",
            questions: [
              { q: "Where did Sarah apply for a job?", options: ["At a department store", "At a hospital", "At a bank"], answer: "At a department store", explanation: "\u0642\u062F\u0645\u062A \u0633\u0627\u0631\u0629 \u0639\u0644\u0649 \u0648\u0638\u064A\u0641\u0629 \u0641\u064A \u0645\u062A\u062C\u0631 \u0643\u0628\u064A\u0631." },
              { q: "What is Sarah going to do tomorrow?", options: ["Sign the contract", "Have an interview", "Write her CV"], answer: "Sign the contract", explanation: "\u0633\u0648\u0641 \u062A\u0648\u0642\u0639 \u0633\u0627\u0631\u0629 \u0627\u0644\u0639\u0642\u062F \u063A\u062F\u0627\u064B \u0628\u0639\u062F \u0642\u0628\u0648\u0644 \u0639\u0631\u0636 \u0627\u0644\u0639\u0645\u0644." }
            ]
          },
          writing: [
            { prompt: "\u0631\u062A\u0628 \u0627\u0644\u0643\u0644\u0645\u0627\u062A: (\u0623\u0646\u0627 \u062A\u062E\u0631\u062C\u062A \u0645\u0646 \u0627\u0644\u062C\u0627\u0645\u0639\u0629 \u0641\u064A \u0639\u0627\u0645 2024.)", words: ["graduated / University / from / 2024 / I / in"], correct: ["I", "graduated", "from", "University", "in", "2024"] },
            { prompt: "\u0623\u0643\u0645\u0644 \u0627\u0644\u0641\u0631\u0627\u063A: I ___ already passed three job interviews this month.", placeholder: "has / have / was", answer: "have" }
          ]
        }
      };
    }
  });

