  var lesson232;
  var init_lesson232 = __esm({
    "js/data/A2/units/unit6/lesson23.js"() {
      lesson232 = {
        id: 23,
        unitId: 6,
        title: "University Studies & Degrees",
        description: "Learn academic terms for higher education, scholarships, degrees, and practice using the passive voice in the present simple.",
        explanation: {
          intro: "\u0623\u0647\u0644\u0627\u064B \u0628\u0643 \u0641\u064A \u0627\u0644\u062F\u0631\u0633 \u0627\u0644\u062B\u0627\u0644\u062B \u0648\u0627\u0644\u0639\u0634\u0631\u064A\u0646! \u0633\u0646\u062A\u0639\u0644\u0645 \u0627\u0644\u064A\u0648\u0645 \u0645\u0635\u0637\u0644\u062D\u0627\u062A \u0623\u0643\u0627\u062F\u064A\u0645\u064A\u0629 \u0645\u062A\u0642\u062F\u0645\u0629 \u062A\u062A\u0639\u0644\u0642 \u0628\u0627\u0644\u062A\u0639\u0644\u064A\u0645 \u0627\u0644\u062C\u0627\u0645\u0639\u064A\u060C \u0648\u0627\u0644\u0645\u0646\u062D \u0627\u0644\u062F\u0631\u0627\u0633\u064A\u0629\u060C \u0648\u0627\u0644\u0634\u0647\u0627\u062F\u0627\u062A \u0627\u0644\u0639\u0644\u064A\u0627 \u0645\u062B\u0644 \u0627\u0644\u0645\u0627\u062C\u0633\u062A\u064A\u0631 \u0648\u0627\u0644\u062F\u0643\u062A\u0648\u0631\u0627\u0647\u060C \u0628\u0627\u0644\u0625\u0636\u0627\u0641\u0629 \u0625\u0644\u0649 \u062F\u0631\u0627\u0633\u0629 \u0635\u064A\u063A\u0629 \u0627\u0644\u0645\u0628\u0646\u064A \u0644\u0644\u0645\u062C\u0647\u0648\u0644 \u0641\u064A \u0627\u0644\u0645\u0636\u0627\u0631\u0639 \u0627\u0644\u0628\u0633\u064A\u0637 (Present Simple Passive).",
          sections: [
            {
              title: "1. Present Simple Passive (\u0627\u0644\u0645\u0628\u0646\u064A \u0644\u0644\u0645\u062C\u0647\u0648\u0644 \u0641\u064A \u0627\u0644\u0645\u0636\u0627\u0631\u0639 \u0627\u0644\u0628\u0633\u064A\u0637)",
              content: "\u0646\u0633\u062A\u062E\u062F\u0645 \u0635\u064A\u063A\u0629 \u0627\u0644\u0645\u0628\u0646\u064A \u0644\u0644\u0645\u062C\u0647\u0648\u0644 \u0639\u0646\u062F\u0645\u0627 \u0646\u0631\u064A\u062F \u0627\u0644\u062A\u0631\u0643\u064A\u0632 \u0639\u0644\u0649 \u0627\u0644\u062D\u062F\u062B \u0623\u0648 \u0627\u0644\u0634\u064A\u0621 \u0627\u0644\u0630\u064A \u064A\u062A\u0623\u062B\u0631 \u0628\u0627\u0644\u0641\u0639\u0644 \u0628\u062F\u0644\u0627\u064B \u0645\u0646 \u0627\u0644\u0634\u062E\u0635 \u0627\u0644\u0630\u064A \u0642\u0627\u0645 \u0628\u0647. \u064A\u062A\u0643\u0648\u0646 \u0645\u0646:\n- **\u0627\u0644\u0645\u0641\u0639\u0648\u0644 \u0628\u0647 (\u0646\u0627\u0626\u0628 \u0627\u0644\u0641\u0627\u0639\u0644) + is / are + \u0627\u0644\u062A\u0635\u0631\u064A\u0641 \u0627\u0644\u062B\u0627\u0644\u062B \u0644\u0644\u0641\u0639\u0644 (Past Participle)**\n\n\u0623\u0645\u062B\u0644\u0629:\n- A research paper **is written** at the end of the course.\n- Scholarships **are offered** to top students every year.\n- Online exams **are graded** automatically by the system."
            },
            {
              title: "2. Degrees and Higher Education (\u0627\u0644\u0634\u0647\u0627\u062F\u0627\u062A \u0627\u0644\u0623\u0643\u0627\u062F\u064A\u0645\u064A\u0629 \u0648\u0627\u0644\u062A\u0639\u0644\u064A\u0645 \u0627\u0644\u0639\u0627\u0644\u064A)",
              content: "\u0644\u062A\u0635\u0641 \u0645\u0633\u0627\u0631\u0643 \u0627\u0644\u062A\u0639\u0644\u064A\u0645\u064A\u060C \u064A\u0645\u0643\u0646\u0643 \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0645\u0635\u0637\u0644\u062D\u0627\u062A \u0645\u062B\u0644 bachelor (\u0628\u0643\u0627\u0644\u0648\u0631\u064A\u0648\u0633) \u0648 master (\u0645\u0627\u062C\u0633\u062A\u064A\u0631) \u0648 certificate (\u0634\u0647\u0627\u062F\u0629)."
            }
          ]
        },
        vocabulary: [
          { id: 2647, word: "academic", translation: "\u0623\u0643\u0627\u062F\u064A\u0645\u064A / \u062F\u0631\u0627\u0633\u064A", example: "We follow an academic calendar.", exampleTranslation: "\u0627\u062D\u0646\u0627 \u0628\u0646\u0645\u0634\u064A \u0639\u0644\u0649 \u062A\u0642\u0648\u064A\u0645 \u0623\u0643\u0627\u062F\u064A\u0645\u064A." },
          { id: 2648, word: "scholarship", translation: "\u0645\u0646\u062D\u0629 \u062F\u0631\u0627\u0633\u064A\u0629 \u0645\u062C\u0627\u0646\u064A\u0629", example: "He won a scholarship to study abroad.", exampleTranslation: "\u0647\u0648 \u0643\u0633\u0628 \u0645\u0646\u062D\u0629 \u062F\u0631\u0627\u0633\u064A\u0629 \u0644\u0644\u062F\u0631\u0627\u0633\u0629 \u0641\u064A \u0627\u0644\u062E\u0627\u0631\u062C." },
          { id: 2649, word: "tuition", translation: "\u0645\u0635\u0627\u0631\u064A\u0641 \u0627\u0644\u062A\u0639\u0644\u064A\u0645 / \u0627\u0644\u062A\u062F\u0631\u064A\u0633", example: "Tuition fees are rising this year.", exampleTranslation: "\u0645\u0635\u0627\u0631\u064A\u0641 \u0627\u0644\u062A\u0639\u0644\u064A\u0645 \u0628\u062A\u0632\u064A\u062F \u0627\u0644\u0633\u0646\u0629 \u062F\u064A." },
          { id: 2650, word: "fee", translation: "\u0631\u0633\u0648\u0645 \u0645\u0627\u0644\u064A\u0629", example: "Pay the registration fee online.", exampleTranslation: "\u0627\u062F\u0641\u0639 \u0631\u0633\u0648\u0645 \u0627\u0644\u062A\u0633\u062C\u064A\u0644 \u0623\u0648\u0646\u0644\u0627\u064A\u0646." },
          { id: 2651, word: "registration", translation: "\u0639\u0645\u0644\u064A\u0629 \u0627\u0644\u062A\u0633\u062C\u064A\u0644", example: "Registration starts in September.", exampleTranslation: "\u0627\u0644\u062A\u0633\u062C\u064A\u0644 \u0628\u064A\u0628\u062F\u0623 \u0641\u064A \u0634\u0647\u0631 \u0633\u0628\u062A\u0645\u0628\u0631." },
          { id: 2652, word: "application", translation: "\u0637\u0644\u0628 \u062A\u0642\u062F\u064A\u0645", example: "Submit your university application early.", exampleTranslation: "\u0642\u062F\u0645 \u0637\u0644\u0628 \u0627\u0644\u062A\u0642\u062F\u064A\u0645 \u0644\u0644\u062C\u0627\u0645\u0639\u0629 \u0628\u062F\u0631\u064A." },
          { id: 2653, word: "apply", translation: "\u064A\u0642\u062F\u0645 \u0637\u0644\u0628\u0627\u064B / \u064A\u062A\u0642\u062F\u0645 \u0644\u0640", example: "I want to apply for a master's degree.", exampleTranslation: "\u0623\u0646\u0627 \u0639\u0627\u0648\u0632 \u0623\u0642\u062F\u0645 \u0639\u0644\u0649 \u062F\u0631\u062C\u0629 \u0627\u0644\u0645\u0627\u062C\u0633\u062A\u064A\u0631." },
          { id: 2654, word: "enroll", translation: "\u064A\u0633\u062C\u0644 \u0627\u0633\u0645\u0647 / \u064A\u0644\u062A\u062D\u0642", example: "How can I enroll in this course?", exampleTranslation: "\u0625\u0632\u0627\u064A \u0623\u0642\u062F\u0631 \u0623\u0633\u062C\u0644 \u0648\u0623\u0644\u062A\u062D\u0642 \u0628\u0627\u0644\u0643\u0648\u0631\u0633 \u062F\u0647\u061F" },
          { id: 2655, word: "enrollment", translation: "\u0627\u0644\u0627\u0644\u062A\u062D\u0627\u0642 / \u0627\u0644\u0642\u064A\u062F \u0627\u0644\u062F\u0631\u0627\u0633\u064A", example: "Enrollment is open for all students.", exampleTranslation: "\u0628\u0627\u0628 \u0627\u0644\u0627\u0644\u062A\u062D\u0627\u0642 \u0645\u0641\u062A\u0648\u062D \u0644\u0643\u0644 \u0627\u0644\u0637\u0644\u0627\u0628." },
          { id: 2656, word: "department", translation: "\u0642\u0633\u0645 \u062F\u0631\u0627\u0633\u064A", example: "The history department is on the second floor.", exampleTranslation: "\u0642\u0633\u0645 \u0627\u0644\u062A\u0627\u0631\u064A\u062E \u0641\u064A \u0627\u0644\u062F\u0648\u0631 \u0627\u0644\u062A\u0627\u0646\u064A." },
          { id: 2657, word: "faculty", translation: "\u0643\u0644\u064A\u0629 / \u0647\u064A\u0626\u0629 \u0627\u0644\u062A\u062F\u0631\u064A\u0633", example: "She is a member of the science faculty.", exampleTranslation: "\u0647\u064A \u0639\u0636\u0648 \u0641\u064A \u0647\u064A\u0626\u0629 \u062A\u062F\u0631\u064A\u0633 \u0627\u0644\u0639\u0644\u0648\u0645." },
          { id: 2658, word: "dean", translation: "\u0639\u0645\u064A\u062F \u0627\u0644\u0643\u0644\u064A\u0629", example: "The dean welcomed the new students.", exampleTranslation: "\u0627\u0644\u0639\u0645\u064A\u062F \u0631\u062D\u0628 \u0628\u0627\u0644\u0637\u0644\u0627\u0628 \u0627\u0644\u062C\u062F\u0627\u062F." },
          { id: 2659, word: "syllabus", translation: "\u062E\u0637\u0629 \u0627\u0644\u0645\u0627\u062F\u0629 / \u0627\u0644\u0645\u0646\u0647\u062C \u0627\u0644\u062A\u0641\u0635\u064A\u0644\u064A", example: "Read the syllabus on the first day.", exampleTranslation: "\u0627\u0642\u0631\u0623 \u062E\u0637\u0629 \u0627\u0644\u0645\u0627\u062F\u0629 \u0641\u064A \u0623\u0648\u0644 \u064A\u0648\u0645." },
          { id: 2660, word: "curriculum", translation: "\u0627\u0644\u0645\u0646\u0647\u062C \u0627\u0644\u062F\u0631\u0627\u0633\u064A \u0627\u0644\u0639\u0627\u0645", example: "The school curriculum includes computer science.", exampleTranslation: "\u0627\u0644\u0645\u0646\u0647\u062C \u0627\u0644\u062F\u0631\u0627\u0633\u064A \u0644\u0644\u0645\u062F\u0631\u0633\u0629 \u0628\u064A\u0634\u0645\u0644 \u0639\u0644\u0648\u0645 \u0627\u0644\u0643\u0645\u0628\u064A\u0648\u062A\u0631." },
          { id: 2661, word: "term", translation: "\u0641\u0635\u0644 \u062F\u0631\u0627\u0633\u064A / \u062A\u0631\u0645", example: "He passed all courses this term.", exampleTranslation: "\u0647\u0648 \u0646\u062C\u062D \u0641\u064A \u0643\u0644 \u0627\u0644\u0645\u0648\u0627\u062F \u0627\u0644\u062A\u0631\u0645 \u062F\u0647." },
          { id: 2662, word: "credit", translation: "\u0633\u0627\u0639\u0629 \u0645\u0639\u062A\u0645\u062F\u0629", example: "You need 120 credits to graduate.", exampleTranslation: "\u0623\u0646\u062A \u0645\u062D\u062A\u0627\u062C 120 \u0633\u0627\u0639\u0629 \u0645\u0639\u062A\u0645\u062F\u0629 \u0639\u0634\u0627\u0646 \u062A\u062A\u062E\u0631\u062C." },
          { id: 2663, word: "course", translation: "\u0645\u0642\u0631\u0631 \u062F\u0631\u0627\u0633\u064A / \u0643\u0648\u0631\u0633", example: "This English course is very interactive.", exampleTranslation: "\u0645\u0642\u0631\u0631 \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0625\u0646\u062C\u0644\u064A\u0632\u064A\u0629 \u062F\u0647 \u062A\u0641\u0627\u0639\u0644\u064A \u062C\u062F\u0627\u064B." },
          { id: 2664, word: "seminar", translation: "\u0646\u062F\u0648\u0629 \u062F\u0631\u0627\u0633\u064A\u0629 / \u062D\u0644\u0642\u0629 \u0628\u062D\u062B", example: "Attend the research seminar on Friday.", exampleTranslation: "\u0627\u062D\u0636\u0631 \u0646\u062F\u0648\u0629 \u0627\u0644\u0628\u062D\u062B \u064A\u0648\u0645 \u0627\u0644\u062C\u0645\u0639\u0629." },
          { id: 2665, word: "workshop", translation: "\u0648\u0631\u0634\u0629 \u0639\u0645\u0644 \u062A\u062F\u0631\u064A\u0628\u064A\u0629", example: "We have a writing workshop today.", exampleTranslation: "\u0639\u0646\u062F\u0646\u0627 \u0648\u0631\u0634\u0629 \u0639\u0645\u0644 \u0644\u0644\u0643\u062A\u0627\u0628\u0629 \u0627\u0644\u0646\u0647\u0627\u0631\u062F\u0629." },
          { id: 2666, word: "research", translation: "\u0627\u0644\u0628\u062D\u062B \u0627\u0644\u0639\u0644\u0645\u064A", example: "He does research in medicine.", exampleTranslation: "\u0647\u0648 \u0628\u064A\u0639\u0645\u0644 \u0628\u062D\u062B \u0639\u0644\u0645\u064A \u0641\u064A \u0627\u0644\u0637\u0628." },
          { id: 2667, word: "thesis", translation: "\u0623\u0637\u0631\u0648\u062D\u0629 / \u0631\u0633\u0627\u0644\u0629 \u0639\u0644\u0645\u064A\u0629", example: "She is writing her master's thesis.", exampleTranslation: "\u0647\u064A \u0628\u062A\u0643\u062A\u0628 \u0631\u0633\u0627\u0644\u0629 \u0627\u0644\u0645\u0627\u062C\u0633\u062A\u064A\u0631 \u0628\u062A\u0627\u0639\u062A\u0647\u0627." },
          { id: 2668, word: "graduation", translation: "\u062D\u0641\u0644 \u0627\u0644\u062A\u062E\u0631\u062C", example: "My graduation ceremony is next week.", exampleTranslation: "\u062D\u0641\u0644 \u0627\u0644\u062A\u062E\u0631\u062C \u0628\u062A\u0627\u0639\u064A \u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u062C\u0627\u064A." },
          { id: 2669, word: "bachelor", translation: "\u0628\u0643\u0627\u0644\u0648\u0631\u064A\u0648\u0633 / \u0644\u064A\u0633\u0627\u0646\u0633", example: "I have a bachelor's degree in engineering.", exampleTranslation: "\u0639\u0646\u062F\u064A \u0634\u0647\u0627\u062F\u0629 \u0627\u0644\u0628\u0643\u0627\u0644\u0648\u0631\u064A\u0648\u0633 \u0641\u064A \u0627\u0644\u0647\u0646\u062F\u0633\u0629." },
          { id: 2670, word: "master", translation: "\u0645\u0627\u062C\u0633\u062A\u064A\u0631", example: "He completed his master's studies.", exampleTranslation: "\u0647\u0648 \u062E\u0644\u0635 \u062F\u0631\u0627\u0633\u0627\u062A \u0627\u0644\u0645\u0627\u062C\u0633\u062A\u064A\u0631 \u0628\u062A\u0627\u0639\u062A\u0647." },
          { id: 2671, word: "doctorate", translation: "\u062F\u0631\u062C\u0629 \u0627\u0644\u062F\u0643\u062A\u0648\u0631\u0627\u0647", example: "She received a doctorate in history.", exampleTranslation: "\u0647\u064A \u062D\u0635\u0644\u062A \u0639\u0644\u0649 \u0627\u0644\u062F\u0643\u062A\u0648\u0631\u0627\u0647 \u0641\u064A \u0627\u0644\u062A\u0627\u0631\u064A\u062E." },
          { id: 2672, word: "PhD", translation: "\u062F\u0643\u062A\u0648\u0631\u0627\u0647 (\u0627\u062E\u062A\u0635\u0627\u0631)", example: "He got a PhD in physics.", exampleTranslation: "\u0647\u0648 \u062D\u0635\u0644 \u0639\u0644\u0649 \u0627\u0644\u062F\u0643\u062A\u0648\u0631\u0627\u0647 \u0641\u064A \u0627\u0644\u0641\u064A\u0632\u064A\u0627\u0621." },
          { id: 2673, word: "lecturer", translation: "\u0645\u062D\u0627\u0636\u0631 / \u0645\u062F\u0631\u0633 \u062C\u0627\u0645\u0639\u064A", example: "The lecturer was clear and helpful.", exampleTranslation: "\u0627\u0644\u0645\u062D\u0627\u0636\u0631 \u0643\u0627\u0646 \u0648\u0627\u0636\u062D \u0648\u0645\u062A\u0639\u0627\u0648\u0646." },
          { id: 2674, word: "tutor", translation: "\u0645\u0639\u064A\u062F / \u0645\u0639\u0644\u0645 \u062E\u0635\u0648\u0635\u064A", example: "Ask your tutor for help.", exampleTranslation: "\u0627\u0637\u0644\u0628 \u0627\u0644\u0645\u0633\u0627\u0639\u062F\u0629 \u0645\u0646 \u0627\u0644\u0645\u0639\u064A\u062F \u0628\u062A\u0627\u0639\u0643." },
          { id: 2675, word: "advisor", translation: "\u0645\u0633\u062A\u0634\u0627\u0631 \u0623\u0643\u0627\u062F\u064A\u0645\u064A", example: "Meet your academic advisor today.", exampleTranslation: "\u0642\u0627\u0628\u0644 \u0645\u0633\u062A\u0634\u0627\u0631\u0643 \u0627\u0644\u0623\u0643\u0627\u062F\u064A\u0645\u064A \u0627\u0644\u0646\u0647\u0627\u0631\u062F\u0629." },
          { id: 2676, word: "certificate", translation: "\u0634\u0647\u0627\u062F\u0629 \u0625\u062A\u0645\u0627\u0645 \u0623\u0648 \u062A\u062F\u0631\u064A\u0628", example: "You will receive a certificate after the course.", exampleTranslation: "\u0647\u062A\u0633\u062A\u0644\u0645 \u0634\u0647\u0627\u062F\u0629 \u0628\u0639\u062F \u0646\u0647\u0627\u064A\u0629 \u0627\u0644\u0643\u0648\u0631\u0633." }
        ],
        dialogue: {
          title: "University Admission",
          lines: [
            { speaker: "Adel", text: "How are university applications processed here, Hoda?", translation: "\u0637\u0644\u0628\u0627\u062A \u0627\u0644\u062A\u0642\u062F\u064A\u0645 \u0644\u0644\u062C\u0627\u0645\u0639\u0629 \u0628\u062A\u062A\u0639\u0627\u0644\u062C \u0625\u0632\u0627\u064A \u0647\u0646\u0627 \u064A\u0627 \u0647\u062F\u0649\u061F" },
            { speaker: "Hoda", text: "All applications are submitted online, and then they are reviewed by the advisor.", translation: "\u0643\u0644 \u0627\u0644\u0637\u0644\u0628\u0627\u062A \u0628\u062A\u062A\u0642\u062F\u0645 \u0623\u0648\u0646\u0644\u0627\u064A\u0646\u060C \u0648\u0628\u0639\u062F\u064A\u0646 \u0628\u064A\u0631\u0627\u062C\u0639\u0647\u0627 \u0627\u0644\u0645\u0633\u062A\u0634\u0627\u0631 \u0627\u0644\u0623\u0643\u0627\u062F\u064A\u0645\u064A." },
            { speaker: "Adel", text: "Are tuition fees paid at the start of the term?", translation: "\u0647\u0644 \u0645\u0635\u0627\u0631\u064A\u0641 \u0627\u0644\u062A\u0639\u0644\u064A\u0645 \u0628\u062A\u062A\u062F\u0641\u0639 \u0641\u064A \u0628\u062F\u0627\u064A\u0629 \u0627\u0644\u062A\u0631\u0645\u061F" },
            { speaker: "Hoda", text: "Yes, and registration is cancelled if fees are not paid on time.", translation: "\u0623\u0647\u060C \u0648\u0627\u0644\u062A\u0633\u062C\u064A\u0644 \u0628\u064A\u062A\u0644\u063A\u064A \u0644\u0648 \u0627\u0644\u0645\u0635\u0627\u0631\u064A\u0641 \u0645\u062A\u062F\u0641\u0639\u062A\u0634 \u0641\u064A \u0648\u0642\u062A\u0647\u0627." }
          ]
        },
        practice: {
          listening: [
            { text: "He won a scholarship to study abroad.", options: ["scholarship", "tuition", "fee"], answer: "scholarship", hint: "\u0627\u0644\u062F\u0639\u0645 \u0627\u0644\u0645\u0627\u0644\u064A \u0627\u0644\u0645\u062C\u0627\u0646\u064A \u0627\u0644\u0630\u064A \u064A\u062D\u0635\u0644 \u0639\u0644\u064A\u0647 \u0627\u0644\u0637\u0627\u0644\u0628 \u0627\u0644\u0645\u062A\u0641\u0648\u0642 \u0644\u0644\u062F\u0631\u0627\u0633\u0629" },
            { text: "She is writing her master's thesis.", options: ["thesis", "syllabus", "department"], answer: "thesis", hint: "\u0628\u062D\u062B \u0639\u0644\u0645\u064A \u0637\u0648\u064A\u0644 \u064A\u0642\u062F\u0645\u0647 \u0627\u0644\u0637\u0627\u0644\u0628 \u0644\u0646\u064A\u0644 \u062F\u0631\u062C\u0629 \u0639\u0644\u0645\u064A\u0629 \u0645\u062A\u0642\u062F\u0645\u0629" },
            { text: "Meet your academic advisor today.", options: ["advisor", "dean", "lecturer"], answer: "advisor", hint: "\u0627\u0644\u0634\u062E\u0635 \u0627\u0644\u0645\u0633\u0624\u0648\u0644 \u0639\u0646 \u062A\u0648\u062C\u064A\u0647 \u0627\u0644\u0637\u0644\u0627\u0628 \u0648\u0627\u062E\u062A\u064A\u0627\u0631 \u0627\u0644\u0645\u0648\u0627\u062F \u0627\u0644\u0645\u0646\u0627\u0633\u0628\u0629 \u0644\u0647\u0645" }
          ],
          speaking: [
            { text: "Many scholarships are offered to top students", translation: "\u064A\u062A\u0645 \u062A\u0642\u062F\u064A\u0645 \u0627\u0644\u0639\u062F\u064A\u062F \u0645\u0646 \u0627\u0644\u0645\u0646\u062D \u0627\u0644\u062F\u0631\u0627\u0633\u064A\u0629 \u0644\u0644\u0637\u0644\u0627\u0628 \u0627\u0644\u0645\u062A\u0641\u0648\u0642\u064A\u0646." },
            { text: "I want to apply for a master degree", translation: "\u0623\u0631\u064A\u062F \u0627\u0644\u062A\u0642\u062F\u064A\u0645 \u0644\u0644\u062D\u0635\u0648\u0644 \u0639\u0644\u0649 \u062F\u0631\u062C\u0629 \u0627\u0644\u0645\u0627\u062C\u0633\u062A\u064A\u0631." }
          ],
          reading: {
            passage: "Every year, thousands of applications are received by the Cairo University admissions office. For students who want to enroll in the faculty of engineering, a high grade in mathematics is required. Tuition fees are paid online, but some excellent students are awarded full scholarships by the dean. To graduate with a bachelor's degree, a total of 140 credits must be completed. During the final term, a graduation project is done by each group under the supervision of a faculty lecturer.",
            questions: [
              { q: "Who awards full scholarships to excellent students?", options: ["The dean", "The admissions office", "The lecturer"], answer: "The dean", explanation: "\u064A\u0645\u0646\u062D \u0639\u0645\u064A\u062F \u0627\u0644\u0643\u0644\u064A\u0629 \u0627\u0644\u0645\u0646\u062D \u0627\u0644\u062F\u0631\u0627\u0633\u064A\u0629 \u0627\u0644\u0643\u0627\u0645\u0644\u0629 \u0644\u0644\u0637\u0644\u0627\u0628 \u0627\u0644\u0645\u062A\u0641\u0648\u0642\u064A\u0646." },
              { q: "How are tuition fees paid?", options: ["Online", "In cash at the office", "By writing a thesis"], answer: "Online", explanation: "\u064A\u062A\u0645 \u062F\u0641\u0639 \u0627\u0644\u0631\u0633\u0648\u0645 \u0627\u0644\u062F\u0631\u0627\u0633\u064A\u0629 \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A." }
            ]
          },
          writing: [
            { prompt: "\u0631\u062A\u0628 \u0627\u0644\u0643\u0644\u0645\u0627\u062A: (\u0627\u0644\u0645\u062D\u0627\u0636\u0631\u0627\u062A \u062A\u064F\u0644\u0642\u0649 \u0641\u064A \u0627\u0644\u0642\u0627\u0639\u0629 \u0627\u0644\u0643\u0628\u0631\u0649.)", words: ["given / are / in / the / main / hall / lectures"], correct: ["lectures", "are", "given", "in", "the", "main", "hall"] },
            { prompt: "\u0623\u0643\u0645\u0644 \u0627\u0644\u0641\u0631\u0627\u063A: The application ___ reviewed by the admission committee tomorrow.", placeholder: "is / are / will", answer: "is" }
          ]
        }
      };
    }
  });

