  var lesson372;
  var init_lesson372 = __esm({
    "js/data/A2/units/unit10/lesson37.js"() {
      lesson372 = {
        id: 37,
        unitId: 10,
        title: "Scientific Discoveries",
        description: "Learn vocabulary for inventions, laboratory experiments, medicine, and space, and practice using used to to describe past habits and states.",
        explanation: {
          intro: "\u0623\u0647\u0644\u0627\u064B \u0628\u0643 \u0641\u064A \u0627\u0644\u062F\u0631\u0633 \u0627\u0644\u0633\u0627\u0628\u0639 \u0648\u0627\u0644\u062B\u0644\u0627\u062B\u064A\u0646! \u0633\u0646\u062A\u062D\u062F\u062B \u0627\u0644\u064A\u0648\u0645 \u0639\u0646 \u0627\u0644\u0627\u0643\u062A\u0634\u0627\u0641\u0627\u062A \u0627\u0644\u0639\u0644\u0645\u064A\u0629 \u0627\u0644\u0647\u0627\u0645\u0629\u060C \u0648\u062A\u062C\u0627\u0631\u0628 \u0627\u0644\u0645\u062E\u062A\u0628\u0631\u0627\u062A\u060C \u0648\u0627\u0644\u0623\u062F\u0648\u064A\u0629 \u0648\u0639\u0644\u0627\u062C \u0627\u0644\u0623\u0645\u0631\u0627\u0636\u060C \u0628\u0627\u0644\u0625\u0636\u0627\u0641\u0629 \u0625\u0644\u0649 \u0643\u0648\u0643\u0628 \u0627\u0644\u0623\u0631\u0636 \u0648\u0627\u0644\u0641\u0636\u0627\u0621\u060C \u0643\u0645\u0627 \u0633\u0646\u062A\u062F\u0631\u0628 \u0639\u0644\u0649 \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0627\u0644\u0635\u064A\u063A\u0629 \u0627\u0644\u0642\u0648\u0627\u0639\u062F\u064A\u0629 used to \u0644\u0648\u0635\u0641 \u0639\u0627\u062F\u0627\u062A \u0648\u062D\u0627\u0644\u0627\u062A \u0643\u0627\u0646\u062A \u062A\u062D\u062F\u062B \u0641\u064A \u0627\u0644\u0645\u0627\u0636\u064A \u0648\u062A\u063A\u064A\u0631\u062A \u0627\u0644\u0622\u0646.",
          sections: [
            {
              title: "1. Used To (\u0627\u0644\u0627\u0639\u062A\u064A\u0627\u062F \u0641\u064A \u0627\u0644\u0645\u0627\u0636\u064A)",
              content: "\u0646\u0633\u062A\u062E\u062F\u0645 **used to** \u0644\u0644\u062A\u0639\u0628\u064A\u0631 \u0639\u0646 \u0623\u0646\u0634\u0637\u0629 \u0623\u0648 \u0639\u0627\u062F\u0627\u062A \u0623\u0648 \u062D\u0642\u0627\u0626\u0642 \u0643\u0627\u0646\u062A \u0635\u062D\u064A\u062D\u0629 \u0641\u064A \u0627\u0644\u0645\u0627\u0636\u064A \u0648\u0644\u0643\u0646\u0647\u0627 \u0644\u0645 \u062A\u0639\u062F \u0643\u0630\u0644\u0643 \u0627\u0644\u0622\u0646. \u064A\u0623\u062A\u064A \u0628\u0639\u062F\u0647\u0627 \u0627\u0644\u0641\u0639\u0644 \u0641\u064A \u0627\u0644\u0645\u0635\u062F\u0631 (Infinitive):\n- \u0627\u0644\u0625\u062B\u0628\u0627\u062A: **Subject + used to + verb (infinitive)**\n  - People **used to travel** by horse before cars were invented.\n  - We **used to believe** the Earth was flat.\n- \u0627\u0644\u0646\u0641\u064A: **Subject + didn't use to + verb (infinitive)** (\u0644\u0627\u062D\u0638 \u062D\u0630\u0641 \u062D\u0631\u0641 d \u0645\u0646 use):\n  - People **didn't use to have** smartphones in the last century."
            },
            {
              title: "2. Scientific Vocabulary (\u0645\u0641\u0631\u062F\u0627\u062A \u0627\u0644\u0639\u0644\u0648\u0645 \u0648\u0627\u0644\u0627\u0643\u062A\u0634\u0627\u0641\u0627\u062A)",
              content: "\u0627\u062D\u0641\u0638 \u0627\u0644\u0643\u0644\u0645\u0627\u062A \u0627\u0644\u0623\u0633\u0627\u0633\u064A\u0629 \u0627\u0644\u0645\u0631\u062A\u0628\u0637\u0629 \u0628\u0627\u0644\u0627\u062E\u062A\u0631\u0627\u0639\u0627\u062A \u0648\u0627\u0644\u0639\u0644\u0648\u0645 \u0648\u0627\u0644\u0628\u062D\u062B \u0627\u0644\u0623\u0643\u0627\u062F\u064A\u0645\u064A \u0645\u062B\u0644 experiment \u0648 planet \u0648 vaccine \u0648 prove."
            }
          ]
        },
        vocabulary: [
          { id: 3067, word: "scientific", translation: "\u0639\u0644\u0645\u064A / \u0642\u0627\u0626\u0645 \u0639\u0644\u0649 \u0627\u0644\u0639\u0644\u0645", example: "We use scientific methods.", exampleTranslation: "\u0627\u062D\u0646\u0627 \u0628\u0646\u0633\u062A\u062E\u062F\u0645 \u0623\u0633\u0627\u0644\u064A\u0628 \u0639\u0644\u0645\u064A\u0629." },
          { id: 3068, word: "invention", translation: "\u0627\u062E\u062A\u0631\u0627\u0639 \u062C\u062F\u064A\u062F", example: "The lightbulb was a great invention.", exampleTranslation: "\u0627\u0644\u0645\u0635\u0628\u0627\u062D \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0626\u064A \u0643\u0627\u0646 \u0627\u062E\u062A\u0631\u0627\u0639\u0627\u064B \u0639\u0638\u064A\u0645\u0627\u064B." },
          { id: 3069, word: "invent", translation: "\u064A\u062E\u062A\u0631\u0639 \u0634\u064A\u0626\u0627\u064B", example: "Who did invent the telephone?", exampleTranslation: "\u0645\u064A\u0646 \u0627\u0644\u0644\u064A \u0627\u062E\u062A\u0631\u0639 \u0627\u0644\u062A\u0644\u064A\u0641\u0648\u0646\u061F" },
          { id: 3070, word: "inventor", translation: "\u0645\u062E\u062A\u0631\u0639 \u0627\u0644\u0634\u064A\u0621", example: "Thomas Edison was a famous inventor.", exampleTranslation: "\u062A\u0648\u0645\u0627\u0633 \u0625\u062F\u064A\u0633\u0648\u0646 \u0643\u0627\u0646 \u0645\u062E\u062A\u0631\u0639\u0627\u064B \u0645\u0634\u0647\u0648\u0631\u0627\u064B." },
          { id: 3071, word: "experiment", translation: "\u062A\u062C\u0631\u0628\u0629 \u0639\u0644\u0645\u064A\u0629", example: "The chemist did a laboratory experiment.", exampleTranslation: "\u0627\u0644\u0643\u064A\u0645\u064A\u0627\u0626\u064A \u0639\u0645\u0644 \u062A\u062C\u0631\u0628\u0629 \u0641\u064A \u0627\u0644\u0645\u0639\u0645\u0644." },
          { id: 3072, word: "researcher", translation: "\u0628\u0627\u062D\u062B \u0639\u0644\u0645\u064A \u0623\u0648 \u0623\u0643\u0627\u062F\u064A\u0645\u064A", example: "The researcher published his findings.", exampleTranslation: "\u0627\u0644\u0628\u0627\u062D\u062B \u0646\u0634\u0631 \u0627\u0644\u0646\u062A\u0627\u0626\u062C \u0627\u0644\u0644\u064A \u0648\u0635\u0644\u0647\u0627." },
          { id: 3073, word: "theory", translation: "\u0646\u0638\u0631\u064A\u0629 \u0639\u0644\u0645\u064A\u0629", example: "He explained the theory of relativity.", exampleTranslation: "\u0647\u0648 \u0634\u0631\u062D \u0646\u0638\u0631\u064A\u0629 \u0627\u0644\u0646\u0633\u0628\u064A\u0629." },
          { id: 3074, word: "gravity", translation: "\u0627\u0644\u062C\u0627\u0630\u0628\u064A\u0629 \u0627\u0644\u0623\u0631\u0636\u064A\u0629", example: "Gravity pulls objects to the ground.", exampleTranslation: "\u0627\u0644\u062C\u0627\u0630\u0628\u064A\u0629 \u0628\u062A\u0633\u062D\u0628 \u0627\u0644\u0623\u0634\u064A\u0627\u0621 \u0644\u0644\u0623\u0631\u0636." },
          { id: 3075, word: "space", translation: "\u0627\u0644\u0641\u0636\u0627\u0621 \u0627\u0644\u062E\u0627\u0631\u062C\u064A", example: "Astronauts travel into outer space.", exampleTranslation: "\u0631\u0648\u0627\u062F \u0627\u0644\u0641\u0636\u0627\u0621 \u0628\u064A\u0633\u0627\u0641\u0631\u0648\u0627 \u0644\u0644\u0641\u0636\u0627\u0621 \u0627\u0644\u062E\u0627\u0631\u062C\u064A." },
          { id: 3076, word: "planet", translation: "\u0643\u0648\u0643\u0628 \u0641\u0644\u0643\u064A", example: "Mars is the red planet.", exampleTranslation: "\u0627\u0644\u0645\u0631\u064A\u062E \u0647\u0648 \u0627\u0644\u0643\u0648\u0643\u0628 \u0627\u0644\u0623\u062D\u0645\u0631." },
          { id: 3077, word: "star", translation: "\u0646\u062C\u0645 \u0641\u064A \u0627\u0644\u0633\u0645\u0627\u0621", example: "The sun is a medium-sized star.", exampleTranslation: "\u0627\u0644\u0634\u0645\u0633 \u0646\u062C\u0645 \u0645\u062A\u0648\u0633\u0637 \u0627\u0644\u062D\u062C\u0645." },
          { id: 3078, word: "galaxy", translation: "\u0645\u062C\u0631\u0629 \u0643\u0648\u0646\u064A\u0629", example: "Our galaxy is the Milky Way.", exampleTranslation: "\u0627\u0644\u0645\u062C\u0631\u0629 \u0628\u062A\u0627\u0639\u062A\u0646\u0627 \u0647\u064A \u062F\u0631\u0628 \u0627\u0644\u062A\u0628\u0627\u0646\u0629." },
          { id: 3079, word: "telescope", translation: "\u0645\u0642\u0631\u0627\u0628 / \u062A\u0644\u0633\u0643\u0648\u0628 \u0644\u0631\u0635\u062F \u0627\u0644\u0646\u062C\u0648\u0645", example: "Look at the stars through a telescope.", exampleTranslation: "\u0628\u0635 \u0639\u0644\u0649 \u0627\u0644\u0646\u062C\u0648\u0645 \u0645\u0646 \u062E\u0644\u0627\u0644 \u0627\u0644\u062A\u0644\u0633\u0643\u0648\u0628." },
          { id: 3080, word: "microscope", translation: "\u0645\u062C\u0647\u0631 / \u0645\u064A\u0643\u0631\u0648\u0633\u0643\u0648\u0628 \u0644\u0644\u062E\u0644\u0627\u064A\u0627", example: "Cells are examined under a microscope.", exampleTranslation: "\u0627\u0644\u062E\u0644\u0627\u064A\u0627 \u0628\u062A\u062A\u0641\u062D\u0635 \u062A\u062D\u062A \u0627\u0644\u0645\u064A\u0643\u0631\u0648\u0633\u0643\u0648\u0628." },
          { id: 3081, word: "cell", translation: "\u062E\u0644\u064A\u0629 \u062D\u064A\u0629 \u0635\u063A\u064A\u0631\u0629", example: "Our body is made of billions of cells.", exampleTranslation: "\u062C\u0633\u0645\u0646\u0627 \u0628\u064A\u062A\u0643\u0648\u0646 \u0645\u0646 \u0645\u0644\u064A\u0627\u0631\u0627\u062A \u0627\u0644\u062E\u0644\u0627\u064A\u0627." },
          { id: 3082, word: "chemical", translation: "\u0645\u0627\u062F\u0629 \u0643\u064A\u0645\u064A\u0627\u0626\u064A\u0629", example: "Do not touch this dangerous chemical.", exampleTranslation: "\u0645\u0627\u062A\u0644\u0645\u0633\u0634 \u0627\u0644\u0645\u0627\u062F\u0629 \u0627\u0644\u0643\u064A\u0645\u064A\u0627\u0626\u064A\u0629 \u0627\u0644\u062E\u0637\u064A\u0631\u0629 \u062F\u064A." },
          { id: 3083, word: "element", translation: "\u0639\u0646\u0635\u0631 \u0643\u064A\u0645\u064A\u0627\u0626\u064A \u0623\u0633\u0627\u0633\u064A", example: "Oxygen is an essential element.", exampleTranslation: "\u0627\u0644\u0623\u0643\u0633\u062C\u064A\u0646 \u0639\u0646\u0635\u0631 \u0623\u0633\u0627\u0633\u064A \u0648\u0645\u0647\u0645." },
          { id: 3084, word: "substance", translation: "\u0645\u0627\u062F\u0629 \u0635\u0644\u0628\u0629 \u0623\u0648 \u0633\u0627\u0626\u0644\u0629", example: "Water is a liquid substance.", exampleTranslation: "\u0627\u0644\u0645\u064A\u0629 \u0645\u0627\u062F\u0629 \u0633\u0627\u0626\u0644\u0629." },
          { id: 3085, word: "scientist", translation: "\u0639\u0627\u0644\u0645 \u0641\u064A \u0623\u062D\u062F \u0627\u0644\u0639\u0644\u0648\u0645", example: "The scientist won the Nobel Prize.", exampleTranslation: "\u0627\u0644\u0639\u0627\u0644\u0645 \u0643\u0633\u0628 \u062C\u0627\u0626\u0632\u0629 \u0646\u0648\u0628\u0644." },
          { id: 3086, word: "medicine", translation: "\u0639\u0644\u0645 \u0627\u0644\u0637\u0628 / \u0627\u0644\u062F\u0648\u0627\u0621", example: "Take your medicine after lunch.", exampleTranslation: "\u062E\u062F \u062F\u0648\u0627\u0643 \u0628\u0639\u062F \u0627\u0644\u063A\u062F\u0627." },
          { id: 3087, word: "cure", translation: "\u0639\u0644\u0627\u062C \u0637\u0628\u064A / \u064A\u0634\u0641\u064A \u0645\u0631\u0636\u0627", example: "Scientists hope to find a cure for cancer.", exampleTranslation: "\u0627\u0644\u0639\u0644\u0645\u0627\u0621 \u0628\u064A\u062A\u0645\u0646\u0648\u0627 \u064A\u0644\u0627\u0642\u0648\u0627 \u0639\u0644\u0627\u062C \u0644\u0644\u0633\u0631\u0637\u0627\u0646." },
          { id: 3088, word: "disease", translation: "\u0645\u0631\u0636 \u0635\u062D\u064A", example: "Smoking leads to heart disease.", exampleTranslation: "\u0627\u0644\u062A\u062F\u062E\u064A\u0646 \u0628\u064A\u0624\u062F\u064A \u0644\u0645\u0631\u0636 \u0627\u0644\u0642\u0644\u0628." },
          { id: 3089, word: "virus", translation: "\u0641\u064A\u0631\u0648\u0633 \u0645\u062C\u0647\u0631\u064A", example: "The flu is caused by a virus.", exampleTranslation: "\u0627\u0644\u0623\u0646\u0641\u0644\u0648\u0646\u0632\u0627 \u0628\u064A\u0633\u0628\u0628\u0647\u0627 \u0641\u064A\u0631\u0648\u0633." },
          { id: 3090, word: "vaccine", translation: "\u0644\u0642\u0627\u062D / \u062A\u0637\u0639\u064A\u0645 \u0637\u0628\u064A", example: "The COVID vaccine is safe.", exampleTranslation: "\u0644\u0642\u0627\u062D \u0643\u0648\u0631\u0648\u0646\u0627 \u0622\u0645\u0646." },
          { id: 3091, word: "analyze", translation: "\u064A\u062D\u0644\u0644 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A", example: "We must analyze the blood sample.", exampleTranslation: "\u0644\u0627\u0632\u0645 \u0646\u062D\u0644\u0644 \u0639\u064A\u0646\u0629 \u0627\u0644\u062F\u0645." },
          { id: 3092, word: "analysis", translation: "\u062A\u062D\u0644\u064A\u0644 \u062F\u0642\u064A\u0642", example: "The chemical analysis took two days.", exampleTranslation: "\u0627\u0644\u062A\u062D\u0644\u064A\u0644 \u0627\u0644\u0643\u064A\u0645\u064A\u0627\u0626\u064A \u0623\u062E\u062F \u064A\u0648\u0645\u064A\u0646." },
          { id: 3093, word: "data", translation: "\u0628\u064A\u0627\u0646\u0627\u062A \u0648\u0645\u0639\u0644\u0648\u0645\u0627\u062A \u0643\u0645\u0628\u064A\u0648\u062A\u0631", example: "Store the research data on the computer.", exampleTranslation: "\u0627\u062D\u0641\u0638 \u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0628\u062D\u062B \u0639\u0644\u0649 \u0627\u0644\u0643\u0645\u0628\u064A\u0648\u062A\u0631." },
          { id: 3094, word: "result", translation: "\u0646\u062A\u064A\u062C\u0629 \u062A\u062C\u0631\u0628\u0629 \u0623\u0648 \u0627\u062E\u062A\u0628\u0627\u0631", example: "The test result was positive.", exampleTranslation: "\u0646\u062A\u064A\u062C\u0629 \u0627\u0644\u0627\u062E\u062A\u0628\u0627\u0631 \u0643\u0627\u0646\u062A \u0625\u064A\u062C\u0627\u0628\u064A\u0629." },
          { id: 3095, word: "prove", translation: "\u064A\u062B\u0628\u062A \u0628\u0627\u0644\u0628\u0631\u0647\u0627\u0646", example: "Can you prove your theory?", exampleTranslation: "\u062A\u0642\u062F\u0631 \u062A\u062B\u0628\u062A \u0648\u062A\u0628\u0631\u0647\u0646 \u0646\u0638\u0631\u064A\u062A\u0643\u061F" },
          { id: 3096, word: "proof", translation: "\u0628\u0631\u0647\u0627\u0646 / \u0625\u062B\u0628\u0627\u062A \u0642\u0627\u0637\u0639", example: "We have scientific proof.", exampleTranslation: "\u0639\u0646\u062F\u0646\u0627 \u0625\u062B\u0628\u0627\u062A \u0648\u0628\u0631\u0647\u0627\u0646 \u0639\u0644\u0645\u064A." }
        ],
        dialogue: {
          title: "Astronomy & Medicine",
          lines: [
            { speaker: "Adel", text: "People used to believe that the Earth was the center of the universe, didn't they, Hoda?", translation: "\u0627\u0644\u0646\u0627\u0633 \u0643\u0627\u0646\u0648\u0627 \u0628\u064A\u0639\u062A\u0642\u062F\u0648\u0627 \u0625\u0646 \u0627\u0644\u0623\u0631\u0636 \u0647\u064A \u0645\u0631\u0643\u0632 \u0627\u0644\u0643\u0648\u0646\u060C \u0645\u0634 \u0643\u062F\u0647 \u064A\u0627 \u0647\u062F\u0649\u061F" },
            { speaker: "Hoda", text: "Yes, until scientists used telescopes to prove that it is just a planet orbiting a star.", translation: "\u0623\u0647\u060C \u0644\u062D\u062F \u0645\u0627 \u0627\u0644\u0639\u0644\u0645\u0627\u0621 \u0627\u0633\u062A\u062E\u062F\u0645\u0648\u0627 \u0627\u0644\u062A\u0644\u0633\u0643\u0648\u0628\u0627\u062A \u0639\u0634\u0627\u0646 \u064A\u062B\u0628\u062A\u0648\u0627 \u0625\u0646\u0647\u0627 \u0645\u062C\u0631\u062F \u0643\u0648\u0643\u0628 \u0628\u064A\u062F\u0648\u0631 \u062D\u0648\u0644 \u0646\u062C\u0645." },
            { speaker: "Adel", text: "Also, medicine used to be less effective before researchers discovered vaccines.", translation: "\u0648\u0643\u0645\u0627\u0646\u060C \u0627\u0644\u0637\u0628 \u0643\u0627\u0646 \u0623\u0642\u0644 \u0641\u0627\u0639\u0644\u064A\u0629 \u0642\u0628\u0644 \u0645\u0627 \u0627\u0644\u0628\u0627\u062D\u062B\u064A\u0646 \u064A\u0643\u062A\u0634\u0641\u0648\u0627 \u0627\u0644\u0644\u0642\u0627\u062D\u0627\u062A." },
            { speaker: "Hoda", text: "True, now many dangerous virus diseases are cured thanks to laboratory experiments.", translation: "\u062D\u0642\u064A\u0642\u064A\u060C \u062F\u0644\u0648\u0642\u062A\u064A \u0623\u0645\u0631\u0627\u0636 \u0641\u064A\u0631\u0648\u0633\u064A\u0629 \u062E\u0637\u064A\u0631\u0629 \u0643\u062A\u064A\u0631\u0629 \u0628\u062A\u062A\u0639\u0627\u0644\u062C \u0628\u0641\u0636\u0644 \u062A\u062C\u0627\u0631\u0628 \u0627\u0644\u0645\u062E\u062A\u0628\u0631\u0627\u062A." }
          ]
        },
        practice: {
          listening: [
            { text: "Thomas Edison was a famous inventor.", options: ["inventor", "researcher", "scientist"], answer: "inventor", hint: "\u0627\u0644\u0634\u062E\u0635 \u0627\u0644\u0630\u064A \u064A\u0628\u062A\u0643\u0631 \u0648\u064A\u0635\u0646\u0639 \u062C\u0647\u0627\u0632\u0627\u064B \u0623\u0648 \u0634\u064A\u0626\u0627\u064B \u062C\u062F\u064A\u062F\u0627\u064B \u0644\u0645 \u064A\u0643\u0646 \u0645\u0648\u062C\u0648\u062F\u0627\u064B \u0645\u0646 \u0642\u0628\u0644" },
            { text: "Oxygen is an essential element.", options: ["element", "substance", "chemical"], answer: "element", hint: "\u0627\u0644\u0645\u0627\u062F\u0629 \u0627\u0644\u0643\u064A\u0645\u064A\u0627\u0626\u064A\u0629 \u0627\u0644\u0628\u0633\u064A\u0637\u0629 \u0627\u0644\u062A\u064A \u0644\u0627 \u064A\u0645\u0643\u0646 \u062A\u0642\u0633\u064A\u0645\u0647\u0627 \u0625\u0644\u0649 \u0645\u0648\u0627\u062F \u0623\u0635\u063A\u0631 \u0645\u0646\u0647\u0627" },
            { text: "Look at the stars through a telescope.", options: ["telescope", "microscope", "vaccine"], answer: "telescope", hint: "\u0627\u0644\u0623\u062F\u0627\u0629 \u0627\u0644\u0628\u0635\u0631\u064A\u0629 \u0627\u0644\u0623\u0646\u0628\u0648\u0628\u064A\u0629 \u0627\u0644\u062A\u064A \u0646\u0633\u062A\u062E\u062F\u0645\u0647\u0627 \u0644\u062A\u0642\u0631\u064A\u0628 \u0648\u0631\u0635\u062F \u0627\u0644\u0643\u0648\u0627\u0643\u0628 \u0648\u0627\u0644\u0646\u062C\u0648\u0645 \u0627\u0644\u0628\u0639\u064A\u062F\u0629" }
          ],
          speaking: [
            { text: "Gravity pulls objects to the ground", translation: "\u0627\u0644\u062C\u0627\u0630\u0628\u064A\u0629 \u062A\u0633\u062D\u0628 \u0627\u0644\u0623\u062C\u0633\u0627\u0645 \u0625\u0644\u0649 \u0627\u0644\u0623\u0631\u0636." },
            { text: "We have scientific proof for the theory", translation: "\u0644\u062F\u064A\u0646\u0627 \u0625\u062B\u0628\u0627\u062A \u0639\u0644\u0645\u064A \u0644\u0644\u0646\u0638\u0631\u064A\u0629." }
          ],
          reading: {
            passage: "In the past, human life used to be very different. People didn't use to understand how diseases spread, so viruses killed millions. However, scientific research changed everything. In modern laboratories, scientists analyze cells under the microscope and perform chemical experiments to create vaccines. Thanks to these discoveries, doctors can now cure diseases that used to be fatal. In addition, astronomers use massive telescopes to study planets and stars in our galaxy, proving new space theories every decade.",
            questions: [
              { q: "What did people not use to understand in the past?", options: ["How diseases spread", "How to use gravity", "How to build telescopes"], answer: "How diseases spread", explanation: "\u0644\u0645 \u064A\u0643\u0646 \u0627\u0644\u0646\u0627\u0633 \u0641\u064A \u0627\u0644\u0645\u0627\u0636\u064A \u064A\u0641\u0647\u0645\u0648\u0646 \u0643\u064A\u0641\u064A\u0629 \u0627\u0646\u062A\u0634\u0627\u0631 \u0627\u0644\u0623\u0645\u0631\u0627\u0636 \u0648\u0627\u0644\u0641\u064A\u0631\u0648\u0633\u0627\u062A." },
              { q: "What do scientists use to analyze cells?", options: ["A microscope", "A telescope", "A solar panel"], answer: "A microscope", explanation: "\u064A\u0633\u062A\u062E\u062F\u0645 \u0627\u0644\u0639\u0644\u0645\u0627\u0621 \u0627\u0644\u0645\u062C\u0647\u0631 (\u0627\u0644\u0645\u064A\u0643\u0631\u0648\u0633\u0643\u0648\u0628) \u0644\u0641\u062D\u0635 \u0648\u062A\u062D\u0644\u064A\u0644 \u0627\u0644\u062E\u0644\u0627\u064A\u0627 \u0627\u0644\u062D\u064A\u0629." }
            ]
          },
          writing: [
            { prompt: "\u0631\u062A\u0628 \u0627\u0644\u0643\u0644\u0645\u0627\u062A: (\u0627\u0644\u0646\u0627\u0633 \u0627\u0639\u062A\u0627\u062F\u0648\u0627 \u0627\u0644\u0633\u0641\u0631 \u0639\u0644\u0649 \u0627\u0644\u062C\u0645\u0627\u0644 \u0641\u064A \u0627\u0644\u0635\u062D\u0631\u0627\u0621.)", words: ["used / camels / travel / to / people / on / in / desert / the"], correct: ["people", "used", "to", "travel", "on", "camels", "in", "the", "desert"] },
            { prompt: "\u0623\u0643\u0645\u0644 \u0627\u0644\u0641\u0631\u0627\u063A: We ___ use to have computers in schools forty years ago.", placeholder: "didn't / don't / did not to", answer: "didn't" }
          ]
        }
      };
    }
  });

