  var lesson382;
  var init_lesson382 = __esm({
    "js/data/A2/units/unit10/lesson38.js"() {
      lesson382 = {
        id: 38,
        unitId: 10,
        title: "Computers & Programming",
        description: "Learn vocabulary for laptops, software development, coding, and databases, and practice using the first conditional with as long as and provided that.",
        explanation: {
          intro: "\u0645\u0631\u062D\u0628\u0627\u064B \u0628\u0643 \u0641\u064A \u0627\u0644\u062F\u0631\u0633 \u0627\u0644\u062B\u0627\u0645\u0646 \u0648\u0627\u0644\u062B\u0644\u0627\u062B\u064A\u0646! \u0633\u0646\u062A\u062D\u062F\u062B \u0627\u0644\u064A\u0648\u0645 \u0639\u0646 \u0623\u062C\u0647\u0632\u0629 \u0627\u0644\u0643\u0645\u0628\u064A\u0648\u062A\u0631\u060C \u0648\u0627\u0644\u0628\u0631\u0645\u062C\u0629\u060C \u0648\u0627\u0644\u062A\u0631\u0645\u064A\u0632 \u0648\u0644\u063A\u0627\u062A \u0627\u0644\u062A\u0637\u0648\u064A\u0631\u060C \u0648\u0642\u0648\u0627\u0639\u062F \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0648\u062D\u0641\u0638 \u0627\u0644\u0645\u0644\u0641\u0627\u062A\u060C \u0628\u0627\u0644\u0625\u0636\u0627\u0641\u0629 \u0625\u0644\u0649 \u062F\u0631\u0627\u0633\u0629 \u0643\u064A\u0641\u064A\u0629 \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0631\u0648\u0627\u0628\u0637 \u0627\u0644\u0634\u0631\u0637 \u0627\u0644\u0623\u0648\u0644 \u0627\u0644\u0645\u062A\u0642\u062F\u0645\u0629 \u0645\u062B\u0644 as long as (\u0637\u0627\u0644\u0645\u0627) \u0648 provided that (\u0628\u0634\u0631\u0637 \u0623\u0646) \u0644\u0644\u062A\u0639\u0628\u064A\u0631 \u0639\u0646 \u0634\u0631\u0648\u0637 \u062D\u062A\u0645\u064A\u0629 \u0641\u064A \u0627\u0644\u0645\u0633\u062A\u0642\u0628\u0644.",
          sections: [
            {
              title: "1. Conditionals: As Long As & Provided That (\u0631\u0648\u0627\u0628\u0637 \u0627\u0644\u0634\u0631\u0637)",
              content: "\u0646\u0633\u062A\u062E\u062F\u0645 **as long as** \u0648 **provided that** \u0644\u0631\u0628\u0637 \u062C\u0645\u0644 \u0627\u0644\u0634\u0631\u0637 \u0645\u0646 \u0627\u0644\u0646\u0648\u0639 \u0627\u0644\u0623\u0648\u0644 \u0628\u062F\u0644\u0627\u064B \u0645\u0646 **if** \u0644\u0644\u062A\u0623\u0643\u064A\u062F \u0639\u0644\u0649 \u0627\u0644\u0634\u0631\u0637. \u064A\u0623\u062A\u064A \u0628\u0639\u062F\u0647\u0645\u0627 \u0645\u0636\u0627\u0631\u0639 \u0628\u0633\u064A\u0637 \u062B\u0645 \u0627\u0644\u0645\u0633\u062A\u0642\u0628\u0644 \u0627\u0644\u0628\u0633\u064A\u0637:\n- **as long as / provided that + \u0645\u0636\u0627\u0631\u0639 \u0628\u0633\u064A\u0637, will + \u0627\u0644\u0645\u0635\u062F\u0631**\n\n\u0623\u0645\u062B\u0644\u0629:\n- You will learn coding **as long as** you practice every day.\n- We will host the app on the server **provided that** the system is secure."
            },
            {
              title: "2. Computing & Tech Vocabulary (\u0645\u0641\u0631\u062F\u0627\u062A \u0627\u0644\u062D\u0648\u0633\u0628\u0629 \u0648\u0627\u0644\u062A\u0642\u0646\u064A\u0629)",
              content: "\u062A\u0639\u0644\u0645 \u0627\u0644\u0643\u0644\u0645\u0627\u062A \u0627\u0644\u0636\u0631\u0648\u0631\u064A\u0629 \u0644\u0644\u062A\u0639\u0627\u0645\u0644 \u0645\u0639 \u0627\u0644\u0628\u0631\u0627\u0645\u062C \u0648\u0627\u0644\u0645\u0644\u0641\u0627\u062A \u0648\u0627\u0644\u0623\u0645\u0646 \u0627\u0644\u0631\u0642\u0645\u064A \u0645\u062B\u0644 database \u0648 cybersecurity \u0648 hardware."
            }
          ]
        },
        vocabulary: [
          { id: 3097, word: "computing", translation: "\u0639\u0644\u0645 \u0627\u0644\u062D\u0648\u0633\u0628\u0629 \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0627\u0644\u0643\u0645\u0628\u064A\u0648\u062A\u0631", example: "He has a degree in computing.", exampleTranslation: "\u0647\u0648 \u0639\u0646\u062F\u0647 \u0634\u0647\u0627\u062F\u0629 \u0641\u064A \u0627\u0644\u062D\u0648\u0633\u0628\u0629." },
          { id: 3098, word: "programming", translation: "\u0639\u0645\u0644\u064A\u0629 \u0627\u0644\u0628\u0631\u0645\u062C\u0629", example: "Programming requires logical thinking.", exampleTranslation: "\u0627\u0644\u0628\u0631\u0645\u062C\u0629 \u0628\u062A\u062D\u062A\u0627\u062C \u062A\u0641\u0643\u064A\u0631 \u0645\u0646\u0637\u0642\u064A." },
          { id: 3099, word: "programmer", translation: "\u0645\u0628\u0631\u0645\u062C \u0643\u0645\u0628\u064A\u0648\u062A\u0631", example: "The programmer fixed the system bug.", exampleTranslation: "\u0627\u0644\u0645\u0628\u0631\u0645\u062C \u0635\u0644\u062D \u062E\u0637\u0623 \u0627\u0644\u0646\u0638\u0627\u0645 \u0627\u0644\u0628\u0631\u0645\u064A." },
          { id: 3100, word: "code", translation: "\u0634\u0641\u0631\u0629 / \u0643\u0648\u062F \u0628\u0631\u0645\u064A", example: "Write a clean code.", exampleTranslation: "\u0627\u0643\u062A\u0628 \u0643\u0648\u062F \u0628\u0631\u0645\u064A \u0646\u0638\u064A\u0641." },
          { id: 3101, word: "development", translation: "\u062A\u0637\u0648\u064A\u0631 \u0627\u0644\u0628\u0631\u0645\u062C\u064A\u0627\u062A", example: "Software development is a growing field.", exampleTranslation: "\u062A\u0637\u0648\u064A\u0631 \u0627\u0644\u0628\u0631\u0645\u062C\u064A\u0627\u062A \u0645\u062C\u0627\u0644 \u0645\u062A\u0646\u0627\u0645\u064A." },
          { id: 3102, word: "hardware", translation: "\u0645\u0643\u0648\u0646\u0627\u062A \u0645\u0627\u062F\u064A\u0629 \u0644\u0644\u0643\u0645\u0628\u064A\u0648\u062A\u0631", example: "Computer hardware includes the CPU.", exampleTranslation: "\u0645\u0643\u0648\u0646\u0627\u062A \u0627\u0644\u0643\u0645\u0628\u064A\u0648\u062A\u0631 \u0627\u0644\u0645\u0627\u062F\u064A\u0629 \u0628\u062A\u0634\u0645\u0644 \u0627\u0644\u0645\u0639\u0627\u0644\u062C." },
          { id: 3103, word: "monitor", translation: "\u0634\u0627\u0634\u0629 \u0639\u0631\u0636 \u0627\u0644\u0643\u0645\u0628\u064A\u0648\u062A\u0631", example: "I bought a new 24-inch monitor.", exampleTranslation: "\u0627\u0634\u062A\u0631\u064A\u062A \u0634\u0627\u0634\u0629 \u0639\u0631\u0636 \u062C\u062F\u064A\u062F\u0629 \u0623\u0631\u0628\u0639\u0629 \u0648\u0639\u0634\u0631\u064A\u0646 \u0628\u0648\u0635\u0629." },
          { id: 3104, word: "key", translation: "\u0645\u0641\u062A\u0627\u062D \u0644\u0648\u062D\u0629 \u0627\u0644\u0645\u0641\u0627\u062A\u064A\u062D", example: "Press the enter key.", exampleTranslation: "\u0627\u0636\u063A\u0637 \u0639\u0644\u0649 \u0645\u0641\u062A\u0627\u062D \u0627\u0644\u0625\u062F\u062E\u0627\u0644." },
          { id: 3105, word: "cursor", translation: "\u0645\u0624\u0634\u0631 \u0627\u0644\u0645\u0627\u0648\u0633 / \u0627\u0644\u0633\u0647\u0645", example: "Move the cursor to the link.", exampleTranslation: "\u062D\u0631\u0643 \u0645\u0624\u0634\u0631 \u0627\u0644\u0645\u0627\u0648\u0633 \u0639\u0644\u0649 \u0627\u0644\u0631\u0627\u0628\u0637." },
          { id: 3106, word: "laptop", translation: "\u0643\u0645\u0628\u064A\u0648\u062A\u0631 \u0645\u062D\u0645\u0648\u0644", example: "I take my laptop to work.", exampleTranslation: "\u0623\u0646\u0627 \u0628\u0627\u062E\u062F \u0627\u0644\u0644\u0627\u0628\u062A\u0648\u0628 \u0628\u062A\u0627\u0639\u064A \u0627\u0644\u0634\u063A\u0644." },
          { id: 3107, word: "desktop", translation: "\u0643\u0645\u0628\u064A\u0648\u062A\u0631 \u0645\u0643\u062A\u0628\u064A", example: "Desktop computers are powerful.", exampleTranslation: "\u0623\u062C\u0647\u0632\u0629 \u0627\u0644\u0643\u0645\u0628\u064A\u0648\u062A\u0631 \u0627\u0644\u0645\u0643\u062A\u0628\u064A\u0629 \u0642\u0648\u064A\u0629." },
          { id: 3108, word: "server", translation: "\u062E\u0627\u062F\u0645 \u0634\u0628\u0643\u0629 \u062E\u0627\u062F\u0645 \u0628\u064A\u0627\u0646\u0627\u062A", example: "The server is offline for maintenance.", exampleTranslation: "\u0627\u0644\u062E\u0627\u062F\u0645 \u063A\u064A\u0631 \u0645\u062A\u0635\u0644 \u0628\u0627\u0644\u0634\u0628\u0643\u0629 \u0644\u0625\u062C\u0631\u0627\u0621 \u0627\u0644\u0635\u064A\u0627\u0646\u0629." },
          { id: 3109, word: "database", translation: "\u0642\u0627\u0639\u062F\u0629 \u0628\u064A\u0627\u0646\u0627\u062A", example: "We store customer details in a database.", exampleTranslation: "\u0628\u0646\u062E\u0632\u0646 \u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0639\u0645\u0644\u0627\u0621 \u0641\u064A \u0642\u0627\u0639\u062F\u0629 \u0628\u064A\u0627\u0646\u0627\u062A." },
          { id: 3110, word: "cloud storage", translation: "\u062A\u062E\u0632\u064A\u0646 \u0633\u062D\u0627\u0628\u064A \u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A", example: "Backup files in the cloud storage.", exampleTranslation: "\u0627\u0639\u0645\u0644 \u0646\u0633\u062E\u0629 \u0627\u062D\u062A\u064A\u0627\u0637\u064A\u0629 \u0644\u0644\u0645\u0644\u0641\u0627\u062A \u0641\u064A \u0627\u0644\u062A\u062E\u0632\u064A\u0646 \u0627\u0644\u0633\u062D\u0627\u0628\u064A." },
          { id: 3111, word: "file", translation: "\u0645\u0644\u0641 \u0631\u0642\u0645\u064A", example: "Do not delete this system file.", exampleTranslation: "\u0645\u0627\u062A\u0645\u0633\u062D\u0634 \u0645\u0644\u0641 \u0627\u0644\u0646\u0638\u0627\u0645 \u062F\u0647." },
          { id: 3112, word: "folder", translation: "\u0645\u062C\u0644\u062F \u0645\u0644\u0641\u0627\u062A \u0631\u0642\u0645\u064A", example: "Create a new folder on the desktop.", exampleTranslation: "\u0627\u0639\u0645\u0644 \u0645\u062C\u0644\u062F \u062C\u062F\u064A\u062F \u0639\u0644\u0649 \u0633\u0637\u062D \u0627\u0644\u0645\u0643\u062A\u0628." },
          { id: 3113, word: "search", translation: "\u064A\u0628\u062D\u062B \u0641\u064A \u0627\u0644\u062C\u0647\u0627\u0632", example: "Search for the document by name.", exampleTranslation: "\u0627\u0628\u062D\u062B \u0639\u0646 \u0627\u0644\u0648\u062B\u064A\u0642\u0629 \u0628\u0627\u0644\u0627\u0633\u0645." },
          { id: 3114, word: "system", translation: "\u0646\u0638\u0627\u0645 \u062A\u0634\u063A\u064A\u0644 \u0643\u0645\u0628\u064A\u0648\u062A\u0631", example: "The operating system needs an update.", exampleTranslation: "\u0646\u0638\u0627\u0645 \u0627\u0644\u062A\u0634\u063A\u064A\u0644 \u0645\u062D\u062A\u0627\u062C \u062A\u062D\u062F\u064A\u062B." },
          { id: 3115, word: "antivirus", translation: "\u0628\u0631\u0646\u0627\u0645\u062C \u0645\u0636\u0627\u062F \u0644\u0644\u0641\u064A\u0631\u0648\u0633\u0627\u062A", example: "Install a powerful antivirus.", exampleTranslation: "\u062B\u0628\u062A \u0628\u0631\u0646\u0627\u0645\u062C \u0645\u0636\u0627\u062F \u0641\u064A\u0631\u0648\u0633\u0627\u062A \u0642\u0648\u064A." },
          { id: 3116, word: "cyber", translation: "\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A / \u0633\u064A\u0628\u0631\u0627\u0646\u064A \u0634\u0628\u0643\u064A", example: "Cyber laws protect users.", exampleTranslation: "\u0627\u0644\u0642\u0648\u0627\u0646\u064A\u0646 \u0627\u0644\u0633\u064A\u0628\u0631\u0627\u0646\u064A\u0629 \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A\u0629 \u0628\u062A\u062D\u0645\u064A \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645\u064A\u0646." },
          { id: 3117, word: "cybersecurity", translation: "\u0627\u0644\u0623\u0645\u0646 \u0627\u0644\u0633\u064A\u0628\u0631\u0627\u0646\u064A \u0627\u0644\u0631\u0642\u0645\u064A", example: "He works in cybersecurity.", exampleTranslation: "\u0647\u0648 \u0628\u064A\u0634\u062A\u063A\u0644 \u0641\u064A \u0645\u062C\u0627\u0644 \u0627\u0644\u0623\u0645\u0646 \u0627\u0644\u0633\u064A\u0628\u0631\u0627\u0646\u064A." },
          { id: 3118, word: "hack", translation: "\u064A\u062E\u062A\u0631\u0642 \u0646\u0638\u0627\u0645\u0627\u064B \u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A\u0627\u064B", example: "They tried to hack our website.", exampleTranslation: "\u062D\u0627\u0648\u0644\u0648\u0627 \u064A\u062E\u062A\u0631\u0642\u0648\u0627 \u0645\u0648\u0642\u0639\u0646\u0627 \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A." },
          { id: 3119, word: "hacker", translation: "\u0645\u062E\u062A\u0631\u0642 \u0623\u0646\u0638\u0645\u0629 / \u0647\u0643\u0631", example: "The hacker stole private data.", exampleTranslation: "\u0627\u0644\u0645\u062E\u062A\u0631\u0642 \u0633\u0631\u0642 \u0628\u064A\u0627\u0646\u0627\u062A \u062E\u0627\u0635\u0629." },
          { id: 3120, word: "user", translation: "\u0645\u0633\u062A\u062E\u062F\u0645 \u0627\u0644\u062C\u0647\u0627\u0632 \u0623\u0648 \u0627\u0644\u0646\u0638\u0627\u0645", example: "The user interface is simple.", exampleTranslation: "\u0648\u0627\u062C\u0647\u0629 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645 \u0628\u0633\u064A\u0637\u0629." },
          { id: 3121, word: "connect", translation: "\u064A\u062A\u0635\u0644 \u0628\u0634\u0628\u0643\u0629", example: "Connect the laptop to the Wi-Fi.", exampleTranslation: "\u0648\u0635\u0644 \u0627\u0644\u0644\u0627\u0628\u062A\u0648\u0628 \u0628\u0627\u0644\u0648\u0627\u064A \u0641\u0627\u064A." },
          { id: 3122, word: "offline", translation: "\u063A\u064A\u0631 \u0645\u062A\u0635\u0644 \u0628\u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A", example: "You can use the app offline.", exampleTranslation: "\u062A\u0642\u062F\u0631 \u062A\u0633\u062A\u062E\u062F\u0645 \u0627\u0644\u062A\u0637\u0628\u064A\u0642 \u0648\u0623\u0646\u062A \u063A\u064A\u0631 \u0645\u062A\u0635\u0644 \u0628\u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A." },
          { id: 3123, word: "printer", translation: "\u0637\u0627\u0628\u0639\u0629 \u0623\u0648\u0631\u0627\u0642", example: "The printer is out of paper.", exampleTranslation: "\u0627\u0644\u0637\u0627\u0628\u0639\u0629 \u062E\u0644\u0635\u062A \u0648\u0631\u0642." },
          { id: 3124, word: "document", translation: "\u0648\u062B\u064A\u0642\u0629 \u0631\u0642\u0645\u064A\u0629 / \u0645\u0633\u062A\u0646\u062F", example: "Save the document before closing.", exampleTranslation: "\u0627\u062D\u0641\u0638 \u0627\u0644\u0645\u0633\u062A\u0646\u062F \u0642\u0628\u0644 \u0627\u0644\u0625\u063A\u0644\u0627\u0642." },
          { id: 3125, word: "coding", translation: "\u0639\u0645\u0644\u064A\u0629 \u0627\u0644\u062A\u0631\u0645\u064A\u0632 / \u0627\u0644\u0628\u0631\u0645\u062C\u0629", example: "Coding is a useful skill.", exampleTranslation: "\u0627\u0644\u062A\u0631\u0645\u064A\u0632 \u0648\u0627\u0644\u0628\u0631\u0645\u062C\u0629 \u0645\u0647\u0627\u0631\u0629 \u0645\u0641\u064A\u062F\u0629." },
          { id: 3126, word: "programming language", translation: "\u0644\u063A\u0629 \u0628\u0631\u0645\u062C\u0629 \u0643\u0645\u0628\u064A\u0648\u062A\u0631", example: "Python is an easy programming language.", exampleTranslation: "\u0628\u0627\u064A\u062B\u0648\u0646 \u0644\u063A\u0629 \u0628\u0631\u0645\u062C\u0629 \u0633\u0647\u0644\u0629." }
        ],
        dialogue: {
          title: "Learning Java",
          lines: [
            { speaker: "Adel", text: "Will you teach me this new programming language, Hoda?", translation: "\u0647\u0644 \u0647\u062A\u0639\u0644\u0645\u064A\u0646\u064A \u0644\u063A\u0629 \u0627\u0644\u0628\u0631\u0645\u062C\u0629 \u0627\u0644\u062C\u062F\u064A\u062F\u0629 \u062F\u064A \u064A\u0627 \u0647\u062F\u0649\u061F" },
            { speaker: "Hoda", text: "I will help you as long as you promise to practice coding every day.", translation: "\u0623\u0646\u0627 \u0647\u0633\u0627\u0639\u062F\u0643 \u0637\u0627\u0644\u0645\u0627 \u0648\u0639\u062F\u062A\u0646\u064A \u0625\u0646\u0643 \u062A\u062A\u062F\u0631\u0628 \u0639\u0644\u0649 \u0627\u0644\u0628\u0631\u0645\u062C\u0629 \u0643\u0644 \u064A\u0648\u0645." },
            { speaker: "Adel", text: "I will. We will finish the database project provided that the server is online.", translation: "\u0647\u0639\u0645\u0644 \u0643\u062F\u0647. \u0648\u0627\u062D\u0646\u0627 \u0647\u0646\u062E\u0644\u0635 \u0645\u0634\u0631\u0648\u0639 \u0642\u0627\u0639\u062F\u0629 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0628\u0634\u0631\u0637 \u0625\u0646 \u0627\u0644\u062E\u0627\u062F\u0645 \u064A\u0643\u0648\u0646 \u0645\u062A\u0635\u0644 \u0628\u0627\u0644\u0634\u0628\u0643\u0629." },
            { speaker: "Hoda", text: "Great! Make sure to save the document file in the cloud storage first.", translation: "\u0645\u0645\u062A\u0627\u0632! \u0627\u062A\u0623\u0643\u062F \u0625\u0646\u0643 \u062A\u062D\u0641\u0638 \u0645\u0644\u0641 \u0627\u0644\u0645\u0633\u062A\u0646\u062F \u0641\u064A \u0627\u0644\u062A\u062E\u0632\u064A\u0646 \u0627\u0644\u0633\u062D\u0627\u0628\u064A \u0627\u0644\u0623\u0648\u0644." }
          ]
        },
        practice: {
          listening: [
            { text: "The programmer fixed the system bug.", options: ["programmer", "hacker", "user"], answer: "programmer", hint: "\u0627\u0644\u0634\u062E\u0635 \u0627\u0644\u0645\u062D\u062A\u0631\u0641 \u0627\u0644\u0630\u064A \u064A\u0643\u062A\u0628 \u0627\u0644\u0623\u0643\u0648\u0627\u062F \u0627\u0644\u0628\u0631\u0645\u062C\u064A\u0629 \u0648\u064A\u0637\u0648\u0631 \u0648\u064A\u0635\u0644\u062D \u0627\u0644\u0623\u0646\u0638\u0645\u0629 \u0648\u0627\u0644\u0628\u0631\u0627\u0645\u062C" },
            { text: "He works in cybersecurity.", options: ["cybersecurity", "hardware", "database"], answer: "cybersecurity", hint: "\u0627\u0644\u0645\u062C\u0627\u0644 \u0627\u0644\u062A\u0642\u0646\u064A \u0627\u0644\u0645\u062E\u062A\u0635 \u0628\u062D\u0645\u0627\u064A\u0629 \u0634\u0628\u0643\u0627\u062A \u0627\u0644\u0643\u0645\u0628\u064A\u0648\u062A\u0631 \u0648\u0627\u0644\u0623\u0646\u0638\u0645\u0629 \u0645\u0646 \u0627\u0644\u0627\u062E\u062A\u0631\u0627\u0642 \u0648\u0627\u0644\u0633\u0631\u0642\u0629" },
            { text: "Backup files in the cloud storage.", options: ["cloud storage", "printer", "monitor"], answer: "cloud storage", hint: "\u0627\u0644\u062A\u062E\u0632\u064A\u0646 \u0627\u0644\u062E\u0627\u0631\u062C\u064A \u0644\u062D\u0641\u0638 \u0627\u0644\u0645\u0644\u0641\u0627\u062A \u0648\u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0639\u0644\u0649 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0644\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064A\u0647\u0627 \u0645\u0646 \u0623\u064A \u0645\u0643\u0627\u0646" }
          ],
          speaking: [
            { text: "Python is an easy programming language", translation: "\u0628\u0627\u064A\u062B\u0648\u0646 \u0647\u064A \u0644\u063A\u0629 \u0628\u0631\u0645\u062C\u0629 \u0633\u0647\u0644\u0629." },
            { text: "Connect the laptop to the wifi", translation: "\u0648\u0635\u0644 \u0627\u0644\u0643\u0645\u0628\u064A\u0648\u062A\u0631 \u0627\u0644\u0645\u062D\u0645\u0648\u0644 \u0628\u0634\u0628\u0643\u0629 \u0627\u0644\u0648\u0627\u064A \u0641\u0627\u064A." }
          ],
          reading: {
            passage: "Tarek is a software developer who works on his laptop from home. He writes code in different programming languages and manages a massive SQL database. Tarek believes that user data is precious, so he is very interested in cybersecurity. He installed a strong antivirus system to protect his files. He says that hackers cannot hack a system provided that the users change their passwords regularly. As long as Tarek connects his device to the network server, he can upload his coding documents to the cloud storage and work offline when needed.",
            questions: [
              { q: "What does Tarek use to protect his files?", options: ["A strong antivirus system", "A wireless printer", "A new monitor"], answer: "A strong antivirus system", explanation: "\u062B\u0628\u062A \u0637\u0627\u0631\u0642 \u0646\u0638\u0627\u0645 \u0645\u0636\u0627\u062F \u0641\u064A\u0631\u0648\u0633\u0627\u062A \u0642\u0648\u064A \u0644\u062D\u0645\u0627\u064A\u0629 \u0645\u0644\u0641\u0627\u062A\u0647 \u0627\u0644\u0631\u0642\u0645\u064A\u0629." },
              { q: "When can hackers not hack a system according to Tarek?", options: ["Provided users change passwords regularly", "As long as the user is offline", "If the computer is a desktop"], answer: "Provided users change passwords regularly", explanation: "\u0628\u0634\u0631\u0637 \u0623\u0646 \u064A\u063A\u064A\u0631 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645\u0648\u0646 \u0643\u0644\u0645\u0627\u062A \u0627\u0644\u0645\u0631\u0648\u0631 \u0628\u0627\u0646\u062A\u0638\u0627\u0645\u060C \u0644\u0646 \u064A\u062A\u0645\u0643\u0646 \u0627\u0644\u0645\u062E\u062A\u0631\u0642\u0648\u0646 \u0645\u0646 \u0627\u0644\u062F\u062E\u0648\u0644." }
            ]
          },
          writing: [
            { prompt: "\u0631\u062A\u0628 \u0627\u0644\u0643\u0644\u0645\u0627\u062A: (\u0633\u0648\u0641 \u0646\u0646\u0647\u064A \u0627\u0644\u062A\u0637\u0648\u064A\u0631 \u0637\u0627\u0644\u0645\u0627 \u0644\u062F\u064A\u0646\u0627 \u0627\u0644\u0648\u0642\u062A.)", words: ["finish / time / have / development / we / as / long / as / we / will"], correct: ["we", "will", "finish", "development", "as", "long", "as", "we", "have", "time"] },
            { prompt: "\u0623\u0643\u0645\u0644 \u0627\u0644\u0641\u0631\u0627\u063A: You can access the database provided ___ you have a password.", placeholder: "that / than / to", answer: "that" }
          ]
        }
      };
    }
  });

