  // js/audioEffects.js
  var AudioEffectsEngine = class {
    constructor() {
      this.ctx = null;
    }
    init() {
      if (!this.ctx) {
        this.ctx = new (window.AudioContext || window.webkitAudioContext)();
      }
      if (this.ctx.state === "suspended") {
        this.ctx.resume();
      }
    }
    isSfxEnabled() {
      return localStorage.getItem("academy_sfx_enabled") !== "false";
    }
    playCorrect() {
      if (!this.isSfxEnabled()) return;
      this.init();
      const now = this.ctx.currentTime;
      this.playTone(523.25, 0.1, now);
      this.playTone(659.25, 0.15, now + 0.08);
    }
    playIncorrect() {
      if (!this.isSfxEnabled()) return;
      this.init();
      const now = this.ctx.currentTime;
      this.playTone(196, 0.15, now, "triangle");
      this.playTone(174.61, 0.25, now + 0.08, "triangle");
    }
    playCelebration() {
      if (!this.isSfxEnabled()) return;
      this.init();
      const now = this.ctx.currentTime;
      this.playTone(523.25, 0.1, now);
      this.playTone(659.25, 0.1, now + 0.08);
      this.playTone(783.99, 0.1, now + 0.16);
      this.playTone(1046.5, 0.3, now + 0.24);
    }
    playTap() {
      if (!this.isSfxEnabled()) return;
      this.init();
      const now = this.ctx.currentTime;
      this.playTone(600, 0.05, now, "sine");
    }
    playTone(freq, duration, startTime, type = "sine") {
      const osc = this.ctx.createOscillator();
      const gainNode = this.ctx.createGain();
      osc.type = type;
      osc.frequency.setValueAtTime(freq, startTime);
      gainNode.gain.setValueAtTime(1e-3, startTime);
      gainNode.gain.linearRampToValueAtTime(0.12, startTime + 0.02);
      gainNode.gain.exponentialRampToValueAtTime(1e-3, startTime + duration);
      osc.connect(gainNode);
      gainNode.connect(this.ctx.destination);
      osc.start(startTime);
      osc.stop(startTime + duration + 0.05);
    }
  };
  var sfx = new AudioEffectsEngine();

