        hintBtn.classList.add("revealed");
        hintBtn.innerHTML = `\u{1F4A1} \u0627\u0644\u0645\u0639\u0646\u0649 \u0628\u0627\u0644\u0639\u0631\u0628\u064A\u0629: <strong style="font-size:1.05rem; color:var(--text-main); margin-right:6px;">${state.arabicHint}</strong>`;
        hintBtn.disabled = true;
        playTone(440, 0.15, "sine", 0.2);
