    /* \u0648\u0645\u064A\u0636 \u0641\u0644\u0627\u0634 \u062D\u0648\u0627\u0641 \u0627\u0644\u0634\u0627\u0634\u0629 \u0644\u0644\u0625\u062C\u0627\u0628\u0629 \u0627\u0644\u0635\u062D\u064A\u062D\u0629 \u0623\u0648 \u0627\u0644\u062E\u0627\u0637\u0626\u0629 */
