  function spawnConfetti3(mount) {
    const colors = ["#6366f1", "#10b981", "#f59e0b", "#ec4899", "#0ea5e9"];
    const container = mount.querySelector(".sb-premium-container") || mount;
    for (let i = 0; i < 40; i++) {
      const el = document.createElement("div");
      el.className = "gc-confetti";
      el.style.cssText = `left:${Math.random() * 100}%;background:${colors[i % colors.length]};animation-delay:${Math.random() * 0.8}s;width:${6 + Math.random() * 6}px;height:${6 + Math.random() * 6}px;border-radius:${Math.random() > 0.5 ? "50%" : "2px"};`;
      container.appendChild(el);
      setTimeout(() => el.remove(), 2600);
    }
  }

  // js/components/gameCenter.js
  var GAME_SCORES_KEY = "eea_game_scores";
  function getGameScores() {
    try {
      return JSON.parse(localStorage.getItem(GAME_SCORES_KEY)) || {};
    } catch {
      return {};
    }
  }
  function saveGameScore(gameId, score) {
    const scores = getGameScores();
    if (!scores[gameId] || score > scores[gameId]) {
      scores[gameId] = score;
      localStorage.setItem(GAME_SCORES_KEY, JSON.stringify(scores));
    }
  }
  function buildVocabPool(lessonIds = null) {
    const pool = [];
    (levelData.curriculum || []).forEach((lesson) => {
      if (lessonIds && !lessonIds.includes(lesson.id)) return;
      (lesson.vocabulary || []).forEach((v) => {
        const english = v.word || v.english;
        const arabic = v.translation || v.arabic;
        if (english && arabic) {
          pool.push({ english, arabic, lessonId: lesson.id, unitId: lesson.unitId });
        }
      });
    });
    return pool;
  }
  function buildSentencePool(lessonIds = null) {
    const pool = [];
    (levelData.curriculum || []).forEach((lesson) => {
      if (lessonIds && !lessonIds.includes(lesson.id)) return;
      const dialogueLines = lesson.dialogue?.lines || lesson.dialogue?.exchanges || [];
      dialogueLines.forEach((line) => {
        const text = line.text || line.english || line.en || line.line;
        const translation = line.translation || line.arabic || line.ar || line.arabicText || "";
        if (text) {
          const cleanedText = text.trim();
          if (cleanedText.split(" ").length >= 4) {
            pool.push({
              sentence: cleanedText,
              translation: translation.trim(),
              lessonId: lesson.id,
              unitId: lesson.unitId
            });
          }
        }
      });
      const practice = lesson.practice || {};
      const exercisesList = [
        ...practice.exercises || [],
        ...practice.listening || [],
        ...practice.speaking || []
      ];
      exercisesList.forEach((ex) => {
        const text = ex.sentence || ex.question || ex.text;
        const translation = ex.translation || ex.arabic || ex.ar || ex.answerTranslation || "";
        if (text) {
          const cleanedText = text.replace(/[.?]/g, "").trim();
          if (cleanedText.split(" ").length >= 4) {
            pool.push({
              sentence: cleanedText,
              translation: translation.trim(),
              lessonId: lesson.id,
              unitId: lesson.unitId
            });
          }
        }
      });
    });
    return pool;
  }
